insert into opspilot_private.training_programs(program_key,version,payload,media_manifest,object_path) values('accueil-client','2026-11-03',$program${"key":"accueil-client","version":"2026-11-03","title":"Accueil client et réclamations : agir avec méthode","category":"Relation client","summary":"Écouter une réclamation, vérifier les faits, proposer une suite précise et protéger les personnes.","audience":"Équipes d’accueil, de caisse, de vente et de restauration ; responsables de proximité.","prerequisites":"Connaître le relais responsable et disposer des procédures commerciales et de sécurité du site.","requirement":"professional","applicability":"Parcours de développement professionnel ; aucune obligation générale de suivre ce module n’est revendiquée.","onsite":"Jeu de rôle avec un collègue puis repérage du relais et du dispositif d’alerte du site. Le responsable observe la reformulation, le respect des limites et la suite annoncée.","objectives":["Reformuler une réclamation en séparant faits, ressenti et demande.","Choisir une réponse dans sa délégation et annoncer une prochaine action vérifiable.","Reconnaître une menace et appliquer le relais de sécurité du site."],"reading_minutes":10,"activity_minutes":8,"sources":[],"chapters":[{"title":"Écouter sans promettre avant de vérifier","body":"# À quoi sert la reformulation ?\nUne réclamation comporte souvent plusieurs éléments : un événement observable, une conséquence pour le client et une solution attendue. Reformuler consiste à vérifier cette compréhension avec lui. Ce n’est ni approuver une accusation ni reconnaître une responsabilité avant d’avoir vérifié les faits.\n\nCas pédagogique fictif : une cliente annonce que sa commande n’est pas prête et qu’elle va rater son rendez-vous. Répondez : « Vous attendiez votre commande à cette heure et vous devez partir bientôt. Je vérifie son état pour vous donner une réponse fiable. » Puis posez une question utile : numéro de commande ou heure annoncée. Évitez de lui faire raconter toute la situation une seconde fois.\n\n« Calmez-vous, ce n’est pas ma faute » déplace la discussion vers un conflit. « Nous allons forcément vous rembourser » promet une décision qui n’est peut-être pas dans votre délégation. Une écoute attentive peut faciliter l’échange, mais ne garantit pas que la personne se calme. Une insulte ou une menace reste un comportement à traiter selon les consignes de sécurité.\n\nAvant de regarder la capsule, formulez à voix haute la différence entre écouter et accepter toutes les demandes. Si vous débutez, utilisez les trois repères : ce qui s’est passé, la conséquence, la demande."},{"title":"Décider, annoncer et passer le relais","body":"# Une réponse utile comporte une prochaine étape\nVérifiez la preuve disponible et la règle applicable : commande, ticket, engagement annoncé, procédure de retour ou de réclamation. Si la situation concerne un prix ou un droit du consommateur, faites vérifier la règle et les faits par le relais compétent ; une politique interne ne supprime pas un droit légal. N’improvisez pas une règle universelle.\n\nPrésentez ce que vous pouvez réellement faire, qui le fait et à quel moment le client recevra une réponse. Dans le cas fictif de la commande : « Je contacte la préparation maintenant. Je reviens vers vous dans deux minutes, même si la vérification n’est pas terminée. » Les deux minutes sont un engagement choisi pour ce cas, pas une norme imposée à tous les magasins. Si ce délai devient impossible, prévenez le client avant de le laisser attendre sans information.\n\nPour transmettre : donnez au collègue les faits vérifiés, la demande du client et ce qui a déjà été proposé. Consignez uniquement les informations nécessaires dans l’outil prévu. Un commentaire comme « client impossible » ne décrit pas un fait utile. Préférez « demande de retour sans ticket, recherche de preuve d’achat en cours ». N’inscrivez pas de donnée personnelle sensible sans nécessité et cadre prévu.\n\nEn cas de menace, gardez une possibilité de retrait, cessez la négociation et appliquez l’alerte du site. Ne poursuivez pas un client, ne cherchez pas à le maîtriser et ne vous exposez pas pour défendre une marchandise."},{"title":"S’entraîner puis vérifier sa méthode","body":"# Cas pédagogique fictif — la commande en retard\nUne cliente affirme avoir payé une commande à retirer à 12 h. À 12 h 10, aucune commande n’est au comptoir. Vous ne savez pas encore si elle est en préparation. Votre délégation vous permet de vérifier et d’appeler le responsable, mais pas de décider seul d’un remboursement.\n\nTravail demandé : rédigez une réponse en trois phrases, puis jouez l’échange avec un collègue. La première reformule. La deuxième annonce une vérification concrète. La troisième précise un retour d’information et un relais si nécessaire. Produisez ensuite une note de transmission de deux lignes, sans jugement sur la personne.\n\nCritères de réussite : aucun remboursement promis avant vérification ; un interlocuteur et une prochaine action identifiés ; un délai réaliste présenté comme un engagement de ce cas ; une limite claire en cas de menace. Pour aller plus loin, rejouez la scène alors que le responsable est occupé : quel autre relais prévu pouvez-vous utiliser ?\n\nPiste de correction : « Vous aviez prévu de repartir à midi avec votre commande. Je vérifie son statut auprès de la préparation. Je reviens vers vous dans deux minutes avec l’information disponible, puis je sollicite le responsable si une décision dépasse ma délégation. » La transmission peut indiquer l’heure promise, l’absence de commande au comptoir et la vérification engagée.\n\nAvant le quiz, expliquez avec vos mots pourquoi une promesse vague ne suffit pas et ce qui change quand la sécurité est en jeu. En cas de difficulté, reprenez le chapitre concerné ou demandez une démonstration au responsable."}],"quiz":[{"question":"Une cliente attend une commande en retard. Quelle première réponse vérifie la compréhension ?","options":["Ce n’est pas mon service.","Vous deviez repartir avec votre commande ; je vérifie son statut.","Le remboursement est garanti."],"question_type":"situation","is_critical":false},{"question":"Quelle promesse est suffisamment précise dans le cas étudié ?","options":["Quelqu’un s’en occupe.","Vous verrez cela plus tard.","Je vérifie auprès de la préparation et reviens dans le délai annoncé."],"question_type":"qcm_single","is_critical":false},{"question":"La décision demandée dépasse votre délégation. Que faites-vous ?","options":["Transmettre les faits au relais compétent et informer le client de la suite.","Inventer une exception.","Dire que les règles légales ne s’appliquent pas dans le magasin."],"question_type":"situation","is_critical":false},{"question":"Un client menace physiquement un collègue. Quelle priorité retenir ?","options":["Finir la vente coûte que coûte.","Préserver les personnes et appliquer la procédure d’alerte.","Le poursuivre à l’extérieur."],"question_type":"critical","is_critical":true},{"question":"Quelle note facilite une transmission professionnelle ?","options":["Cliente insupportable.","Tous les détails de sa vie personnelle.","Commande annoncée à midi, statut vérifié, responsable sollicité."],"question_type":"qcm_single","is_critical":false},{"question":"Une écoute attentive garantit-elle que la personne deviendra raisonnable ?","options":["Non ; elle aide à comprendre, sans supprimer les limites de sécurité.","Oui, dans tous les cas.","Oui, à condition de tout accepter."],"question_type":"qcm_single","is_critical":false}],"video":{"title":"Une réclamation, une prochaine action","scenes":[{"heading":"Écouter. Vérifier. Agir.","lines":["Comprendre la demande","Annoncer une suite précise","Protéger les personnes"],"narration":"Une réclamation ne se résout pas avec une formule magique. Le but est de comprendre le problème, de vérifier ce qui peut être fait et d’annoncer une suite précise. Dans cette capsule, nous suivons un cas pédagogique fictif. Une cliente devait récupérer sa commande à midi. Dix minutes plus tard, elle attend encore."},{"heading":"Séparer les trois éléments","lines":["Fait : la commande manque","Conséquence : un rendez-vous","Demande : repartir rapidement"],"narration":"Commencez par séparer le fait, sa conséquence et la demande. La commande n’est pas au comptoir. La cliente explique qu’elle va rater son rendez-vous. Elle veut repartir rapidement. Vous pouvez dire : vous deviez repartir avec votre commande ; je vérifie son statut. Reformuler ne signifie pas accepter une accusation ou garantir un remboursement."},{"heading":"Vérifier avant de promettre","lines":["Chercher l’information utile","Respecter sa délégation","Identifier le bon relais"],"narration":"Vérifiez l’état de la commande et ce qui avait été annoncé. Si une décision dépasse votre délégation, sollicitez le relais prévu. Ne promettez pas un remboursement pour faire cesser la discussion. Une règle interne ne supprime pas un droit légal : si la situation pose une question de droit, faites vérifier la règle et les faits par le responsable compétent."},{"heading":"Action + personne + retour","lines":["Je contacte la préparation","Je m’en charge maintenant","Je reviens avec l’information"],"narration":"Une prochaine étape utile comporte une action, une personne et un retour d’information. Par exemple : je contacte la préparation maintenant et je reviens vers vous dans deux minutes, même si la vérification n’est pas terminée. Deux minutes est ici un engagement fictif, pas une norme. Si vous ne pouvez plus le tenir, prévenez la cliente."},{"heading":"À vous de jouer","lines":["Reformulez en une phrase","Annoncez votre vérification","Précisez la prochaine étape"],"narration":"Mettez la vidéo en pause. Formulez votre réponse en trois phrases : compréhension, vérification, prochaine étape. Comparez-la ensuite avec cette proposition : vous attendiez votre commande à midi. Je vérifie son statut auprès de la préparation. Je reviens avec l’information disponible, puis je sollicite le responsable si une décision dépasse ma délégation."},{"heading":"La sécurité reste prioritaire","lines":["Aucune promesse impossible","Une trace factuelle et utile","Une alerte si menace"],"narration":"Une écoute attentive ne garantit pas que la personne se calme. En cas de menace, préservez les personnes et appliquez la procédure d’alerte du site. Pour transmettre le dossier, écrivez des faits utiles, sans jugement ni détail personnel inutile. Reprenez le cours écrit, réalisez le jeu de rôle, puis passez au quiz final. La mise en pratique compte autant que les mots choisis."}]},"positioning":["Pouvez-vous expliquer la méthode à un collègue ?","Savez-vous reconnaître les limites de votre rôle ?","Connaissez-vous le relais de votre site ?"]}$program$::jsonb,$media${"key":"accueil-client","version":"2026-11-03","duration_seconds":135.0,"size_bytes":1696355,"sha256":"57cab70c47aa34b8ca474a681f6a97af566aafa4a841b0aeb368f271bbaae3df","width":1280,"height":720,"video_codec":"h264","audio_codec":"aac","narration":"synthetic","voice":"fr_FR-siwis-medium","voice_dataset_license":"CC-BY-4.0","voice_model_card":"https://huggingface.co/rhasspy/piper-voices/blob/main/fr/fr_FR/siwis/medium/MODEL_CARD","captions_burned_in":true,"caption_cues":53,"chapters":[{"title":"Écouter. Vérifier. Agir.","seconds":0.0},{"title":"Séparer les trois éléments","seconds":20.812},{"title":"Vérifier avant de promettre","seconds":42.308},{"title":"Action + personne + retour","seconds":64.177},{"title":"À vous de jouer","seconds":86.092},{"title":"La sécurité reste prioritaire","seconds":110.362}]}$media$::jsonb,'library/2026-11-03/accueil-client/57cab70c47aa34b8ca474a681f6a97af566aafa4a841b0aeb368f271bbaae3df.mp4') on conflict(program_key,version) do nothing;
insert into opspilot_private.training_programs(program_key,version,payload,media_manifest,object_path) values('accueil-securite','2026-11-03',$program${"key":"accueil-securite","version":"2026-11-03","title":"Accueil sécurité : prendre son poste sans s’exposer","category":"Sécurité au travail","summary":"Repérer les risques du site, utiliser les bonnes consignes et transmettre une alerte utile.","audience":"Salariés du magasin ou du restaurant, nouveaux arrivants et personnes changeant de poste ou de conditions de travail.","prerequisites":"Accès aux consignes du site et accompagnement d’un responsable connaissant le poste.","requirement":"internal_required","applicability":"Socle de formation à la sécurité à adapter aux risques réels, au poste, à l’expérience et à la langue comprise. Le responsable complète l’accueil sur site et le renouvelle quand nécessaire.","onsite":"Visite accompagnée : cheminements, zones engins, sorties, alarme, point de rassemblement, secours et interlocuteurs. Faire reformuler puis observer une prise de poste réelle en sécurité.","objectives":["Repérer trois risques de son poste et la protection collective prévue.","Identifier un trajet sûr et le relais à prévenir en cas d’anomalie.","Transmettre une alerte localisée sans se mettre en danger."],"positioning":["Savez-vous qui contacter face à une situation dangereuse ?","Pouvez-vous montrer le cheminement autorisé de votre poste à la sortie ?","Savez-vous où consulter les consignes et le document d’évaluation des risques ?"],"reading_minutes":10,"activity_minutes":10,"sources":[{"label":"Code du travail, R4141-2 à R4141-5 : contenu et adaptation de l’accueil sécurité","url":"https://www.legifrance.gouv.fr/codes/section_lc/LEGITEXT000006072050/LEGISCTA000018488276/"}],"chapters":[{"title":"Voir le risque avant de commencer","body":"# Danger, exposition et prévention\nUn danger est une source possible de dommage : un couteau, un sol glissant, un véhicule en mouvement. Le risque dépend aussi de l’exposition : passer à pied dans une zone de livraison pendant une manœuvre n’a pas les mêmes conséquences qu’un trajet séparé et protégé. Repérer un risque sert à choisir une manière de travailler sûre, avant le premier geste.\n\nCommencez par demander la démonstration du poste : circulation autorisée, charges, matériels, produits utilisés, protections collectives et conduite à tenir face à une anomalie. Une barrière séparant piétons et engins protège plusieurs personnes ; un équipement individuel ne dispense pas de cette séparation. Ne retirez jamais une protection pour accélérer le travail.\n\nCas pédagogique fictif : des cartons occupent le passage prévu entre la réserve et la surface de vente. Les enjamber ne rétablit pas un passage sûr. Arrêtez le déplacement concerné, avertissez le responsable et suivez le chemin autorisé disponible. Si vous devez baliser, faites-le sans vous placer dans la circulation des engins.\n\nLe document unique d’évaluation des risques aide à connaître les risques identifiés et les actions de prévention. Demandez où il est consultable et quelles consignes concernent votre poste. Un document ne remplace pas l’explication sur le terrain. Si la langue, un handicap ou une difficulté de lecture empêche de comprendre une consigne, signalez-le avant de commencer pour obtenir une explication ou une adaptation appropriée."},{"title":"Réagir à l’anomalie sans créer un second accident","body":"# Arrêter, protéger sans s’exposer, alerter\nUne situation anormale est un écart observable : fuite, bruit inhabituel, protecteur manquant, câble abîmé, passage bloqué ou comportement menaçant. Décrivez ce que vous observez. Vous n’avez pas à prouver la cause pour demander une vérification. Ne remettez pas en marche un équipement simplement parce qu’un collègue l’utilisait auparavant.\n\nEn cas d’accident ou de malaise, évitez le suraccident. Prévenez le relais de secours prévu par le site. Si nécessaire, appelez les secours d’urgence : 112 ou 15 pour une urgence médicale, 18 pour les sapeurs-pompiers. Donnez l’adresse exacte, l’accès, la nature du danger, le nombre de personnes concernées et votre numéro de rappel. Suivez les instructions de l’opérateur. Ne déplacez pas une victime sauf nécessité immédiate de la soustraire à un danger et sans vous exposer.\n\nNe touchez pas un équipement électrique endommagé et n’intervenez pas dans une machine pour dégager un produit. Prévenez la personne compétente. L’envie d’aider peut aggraver l’accident si l’énergie ou le danger n’est pas maîtrisé. Ce cours traite l’alerte interne, pas l’acquisition de gestes de secourisme.\n\nAprès la mise en sécurité, transmettez le lieu, l’heure, les faits et les mesures déjà prises. Une trace utile permet de corriger une cause et d’éviter une répétition. Elle ne doit pas devenir une recherche improvisée de faute ou contenir des détails de santé non nécessaires. Le responsable suit ensuite le traitement et informe l’équipe des consignes modifiées."},{"title":"Réaliser sa visite et tester son alerte","body":"# Exercice accompagné sur le site\nAvec le responsable, partez de votre poste et montrez : le cheminement piéton, les zones à ne pas traverser, une sortie, le point de rassemblement, le moyen d’alerte et le lieu où demander les consignes. Demandez qui est votre relais pendant chaque plage horaire, y compris lorsqu’un responsable habituel est absent.\n\nCas pédagogique fictif : un sol mouillé se trouve dans un passage fréquenté et un collègue vient de tomber. Décrivez en une minute l’action immédiate, le relais et le message d’alerte. Livrable : une fiche de repérage avec les lieux et fonctions utiles, sans information personnelle inutile. Ne déclenchez aucun système d’alarme réel pour cet exercice sans l’organisation du responsable.\n\nCritères observés : vous restez hors du danger ; vous signalez le risque aux personnes exposées sans vous mettre en travers d’un engin ; vous donnez une localisation exploitable ; vous identifiez le relais et n’improvisez pas une intervention technique.\n\nPiste de correction : sécuriser l’accès si cela est possible sans risque, appeler le relais de secours, décrire le lieu et l’état observable de la personne, puis suivre ses instructions. Un message « quelqu’un est tombé quelque part » est trop imprécis. Le responsable valide la visite et les gestes réellement démontrés selon sa procédure. Le résultat du quiz ne suffit pas à constater cette validation pratique. Si un repère manque, inscrivez une action à résoudre avant de travailler seul."}],"quiz":[{"question":"Des cartons bloquent le trajet piéton prévu. Que faire ?","options":["Les enjamber rapidement.","Passer dans la zone des engins.","Signaler l’obstacle et utiliser seulement un trajet autorisé sûr."],"question_type":"situation","is_critical":true},{"question":"Une protection collective sert notamment à…","options":["Réduire l’exposition de plusieurs personnes.","Remplacer toute consigne.","Autoriser l’usage d’un équipement défectueux."],"question_type":"qcm_single","is_critical":false},{"question":"Quelle alerte est la plus utile ?","options":["Il y a un problème.","Chute dans le couloir de réserve côté livraison ; passage balisé, relais secours demandé.","Je pense connaître le coupable."],"question_type":"situation","is_critical":false},{"question":"Vous ne comprenez pas une consigne avant la prise de poste. Que faire ?","options":["Deviner en regardant de loin.","Signer puis demander plus tard.","Demander une explication ou une adaptation avant de commencer."],"question_type":"qcm_single","is_critical":false},{"question":"Un câble est abîmé et l’appareil fonctionne encore. Quelle décision prendre ?","options":["Cesser l’utilisation et prévenir le relais compétent sans intervention improvisée.","Continuer jusqu’à la panne.","Réparer soi-même avec du ruban."],"question_type":"critical","is_critical":true},{"question":"Que prouve la réussite du quiz ?","options":["Une habilitation de secouriste.","La réussite de cette évaluation de connaissances, à compléter par l’accueil pratique du site.","La conformité de tout l’établissement."],"question_type":"qcm_single","is_critical":false}],"video":{"title":"Avant le premier geste","scenes":[{"heading":"Avant le premier geste","lines":["Comprendre le poste","Repérer les risques","Savoir qui alerter"],"narration":"Avant de commencer un poste, trois questions doivent avoir une réponse concrète. Où puis-je circuler ? Qu’est-ce qui peut me blesser ou blesser une autre personne ? Qui dois-je prévenir si une situation est anormale ? L’accueil sécurité sert à répondre à ces questions sur votre site, avec les consignes réellement utilisées."},{"heading":"Un danger + une exposition","lines":["Un engin en mouvement","Un piéton sur son trajet","Une séparation à respecter"],"narration":"Un engin est une source de danger. Le risque augmente lorsqu’un piéton se trouve sur son trajet. Respecter le cheminement séparé évite cette exposition. Les protections collectives et l’organisation du travail passent avant l’idée de simplement faire attention. Un équipement individuel ne permet pas d’ignorer une barrière ou un trajet interdit."},{"heading":"Cas fictif : passage bloqué","lines":["Ne pas enjamber","Ne pas improviser un détour","Signaler et demander un trajet sûr"],"narration":"Dans notre cas pédagogique fictif, des cartons bloquent le passage de la réserve. Enjamber les cartons ne règle pas le problème. Passer dans la zone de livraison peut créer un autre danger. Arrêtez le déplacement concerné, signalez l’obstacle et utilisez seulement un chemin autorisé sûr. Le responsable organise la correction."},{"heading":"Une alerte localisée","lines":["Où exactement ?","Quel danger observable ?","Quelle aide est nécessaire ?"],"narration":"Pour alerter, décrivez des faits : le lieu exact, le danger observable et ce qui a déjà été fait. En cas d’accident, évitez le suraccident et prévenez le relais de secours prévu. Si une urgence impose d’appeler les secours, donnez l’adresse et l’accès, puis suivez les instructions de l’opérateur. N’improvisez pas une intervention technique."},{"heading":"À montrer sur place","lines":["Trajet et sortie","Alerte et rassemblement","Consignes et interlocuteurs"],"narration":"Mettez la vidéo en pause. Avec votre responsable, montrez un trajet sûr, la sortie, le moyen d’alerte et le point de rassemblement. Demandez aussi où consulter les risques du poste. Si une consigne n’est pas comprise, demandez une explication adaptée avant de travailler seul. Regarder une vidéo ne remplace pas cette visite."},{"heading":"Comprendre puis démontrer","lines":["Un risque repéré","Une action sûre","Une alerte compréhensible"],"narration":"Retenez cette méthode : repérer le risque, choisir une action qui n’expose personne et transmettre une alerte compréhensible. Poursuivez avec le cours écrit et l’exercice accompagné. Le quiz vérifiera les connaissances ; la démonstration sur le poste restera à organiser et à observer par le responsable."}]}}$program$::jsonb,$media${"key":"accueil-securite","version":"2026-11-03","duration_seconds":123.516372,"size_bytes":1541126,"sha256":"da60cec15437c6a3a25721c2f84dacd8fb5893990fad626aec139cb58a51c064","width":1280,"height":720,"video_codec":"h264","audio_codec":"aac","narration":"synthetic","voice":"fr_FR-siwis-medium","voice_dataset_license":"CC-BY-4.0","voice_model_card":"https://huggingface.co/rhasspy/piper-voices/blob/main/fr/fr_FR/siwis/medium/MODEL_CARD","captions_burned_in":true,"caption_cues":44,"chapters":[{"title":"Avant le premier geste","seconds":0.0},{"title":"Un danger + une exposition","seconds":19.083},{"title":"Cas fictif : passage bloqué","seconds":38.132},{"title":"Une alerte localisée","seconds":58.608},{"title":"À montrer sur place","seconds":81.415},{"title":"Comprendre puis démontrer","seconds":103.701}]}$media$::jsonb,'library/2026-11-03/accueil-securite/da60cec15437c6a3a25721c2f84dacd8fb5893990fad626aec139cb58a51c064.mp4') on conflict(program_key,version) do nothing;
insert into opspilot_private.training_programs(program_key,version,payload,media_manifest,object_path) values('caisse','2026-11-03',$program${"key":"caisse","version":"2026-11-03","title":"Caisse : encaisser juste et protéger les personnes","category":"Encaissement","summary":"Vérifier une opération, appliquer sa délégation et traiter un écart avec une trace fiable.","audience":"Personnel de caisse et responsables de proximité.","prerequisites":"Procédure du site : moyens acceptés, contrôles, délégations, clôture et alerte de sécurité.","requirement":"professional","applicability":"Parcours de professionnalisation à adapter aux moyens de paiement et aux procédures du site ; aucune obligation générale de suivre ce module n’est revendiquée.","onsite":"Démonstration en environnement d’entraînement, sans encaissement réel : ouverture, contrôle d’un paiement, appel du relais et clôture fictive. Vérifier le verrouillage de la session et l’accès aux consignes.","objectives":["Vérifier un paiement dans le système du magasin sans se fier à une preuve externe isolée.","Appliquer les délégations et transmettre une contestation sans improviser une opération.","Rapprocher une clôture et signaler un écart factuel."],"positioning":["Connaissez-vous votre délégation pour les annulations et remboursements ?","Savez-vous reconnaître un paiement confirmé dans le système prévu ?","Pouvez-vous indiquer la conduite de sécurité en cas de menace ?"],"reading_minutes":10,"activity_minutes":10,"sources":[],"chapters":[{"title":"Préparer une caisse et vérifier un paiement","body":"# Exactitude et traçabilité avant la vitesse\nL’ouverture suit la procédure du site : contrôle du fonds, état des équipements, identification personnelle et signalement d’un écart avant l’utilisation. Le montant du fonds et les modalités de double contrôle dépendent de l’établissement. Aucun montant standard ni seuil universel d’annulation n’est fixé par ce cours.\n\nUtilisez votre propre session et verrouillez-la lors d’une absence. Un code partagé efface la possibilité de comprendre qui a réalisé une opération et expose les personnes à une attribution erronée. Ne transmettez pas un mot de passe dans une note, un groupe de discussion ou une capture.\n\nPour encaisser, contrôlez les articles, quantités, réductions et montant avant de demander le règlement. Attendez la confirmation attendue dans le système du magasin. Une capture de téléphone montrée par un client ne prouve pas à elle seule que le paiement est accepté dans votre caisse. Si une opération est incertaine, faites vérifier son état avant de relancer : une répétition peut créer un double paiement.\n\nPour les espèces et autres moyens acceptés, appliquez les contrôles prévus et les règles actuelles de l’établissement. Ne collectez pas de données supplémentaires « par prudence » sans procédure adaptée. Face à un doute sur un billet, un titre ou une opération, faites appel au relais compétent sans accusation ni geste de confrontation."},{"title":"Contestation, clôture et sécurité","body":"# Une anomalie n’autorise pas une opération improvisée\nEn cas de contestation du rendu de monnaie, écoutez, conservez les éléments de l’opération et appliquez la vérification prévue avec le responsable. N’ouvrez pas le tiroir sous la pression d’un récit contradictoire et n’enchaînez pas plusieurs échanges sans stabiliser le premier. Expliquez l’étape de contrôle au client.\n\nLes annulations, remboursements et gestes commerciaux respectent les délégations du site et les droits applicables. Si la demande dépasse votre rôle, transmettez les faits et attendez la validation prévue. Une urgence commerciale n’autorise pas à utiliser le code d’un collègue.\n\nLa clôture rapproche le montant théorique et le comptage réel selon les catégories prévues. Recomptez et vérifiez les opérations sensibles en cas d’écart, consignez la valeur réelle puis transmettez au responsable. Un écart n’est pas, à lui seul, la preuve d’un vol ou d’une faute. Ne modifiez pas les nombres pour obtenir artificiellement zéro. La remise et son transport suivent les consignes de sécurité ; leurs détails ne se partagent pas publiquement.\n\nEn cas de menace ou d’agression, préservez les personnes et appliquez les consignes du site. Ne poursuivez pas un agresseur et ne prenez pas de risque pour protéger des fonds. Un dispositif discret ne doit être utilisé que dans les conditions expliquées, sans provoquer une exposition supplémentaire. Après l’incident, alerte et accompagnement passent avant la reprise précipitée de l’activité."},{"title":"Exercice : paiement incertain et écart fictif","body":"# Deux cas pédagogiques fictifs, aucun règlement réel\nCas 1 : le terminal semble avoir interrompu une transaction et le client montre un écran indiquant un débit. Cas 2 : à la clôture d’entraînement, le comptage diffère du théorique. Les montants éventuellement utilisés par le formateur sont fictifs, sans valeur de seuil légal.\n\nTravail demandé : expliquez ce que vous vérifiez avant toute nouvelle demande de paiement. Pour la clôture, produisez une note indiquant le résultat du recomptage, les éléments consultés et le relais, sans accuser une personne. Livrable : deux décisions et une simulation dans l’environnement d’entraînement autorisé.\n\nPiste de correction : vérifier le statut de l’opération dans le système prévu et demander le relais avant de répéter un débit ; en clôture, garder les chiffres réels, rechercher les éléments utiles et transmettre l’écart selon la procédure. Une capture externe seule ou une supposition ne doit pas devenir une confirmation de caisse.\n\nCritères observés : identification personnelle ; vérification avant répétition ; délégation respectée ; trace factuelle ; confidentialité et sécurité conservées. Pour un débutant, le responsable montre une opération fictive complète avant l’essai. Pour approfondir, ajoutez une contestation de rendu et faites expliciter l’ordre de vérification. Le quiz final mesure la compréhension ; il n’autorise aucun encaissement ou remboursement de test sur un vrai client."}],"quiz":[{"question":"Le statut d’un paiement est incertain et le client montre son téléphone. Que faire avant de relancer ?","options":["Débiter immédiatement une seconde fois.","Vérifier l’état dans le système prévu et demander le relais si nécessaire.","Se fier uniquement à la capture."],"question_type":"situation","is_critical":true},{"question":"Un écart apparaît à la clôture fictive. Quelle réponse retenir ?","options":["Modifier le total pour retrouver zéro.","Accuser le dernier utilisateur.","Recompter, vérifier, garder les valeurs réelles et transmettre selon la procédure."],"question_type":"situation","is_critical":false},{"question":"Quel identifiant utiliser ?","options":["Sa session personnelle, verrouillée en cas d’absence.","Le code du responsable pour aller plus vite.","Une session partagée sans trace."],"question_type":"qcm_single","is_critical":false},{"question":"La demande de remboursement dépasse votre délégation. Que faire ?","options":["Décider seul sous pression.","Transmettre les faits au relais et suivre la validation prévue.","Utiliser le code d’un collègue."],"question_type":"qcm_single","is_critical":false},{"question":"Face à une menace physique, quelle priorité retenir ?","options":["Défendre le tiroir à tout prix.","Poursuivre l’agresseur.","Préserver les personnes et appliquer les consignes de sécurité."],"question_type":"critical","is_critical":true},{"question":"Le fonds de départ et le seuil d’annulation sont-ils universels ?","options":["Non ; consulter la procédure et les délégations du site.","Oui, les mêmes partout.","Oui, le montant se choisit librement à chaque ouverture."],"question_type":"qcm_single","is_critical":false}],"video":{"title":"Une caisse juste sans opération improvisée","scenes":[{"heading":"Préparer avant d’encaisser","lines":["Session personnelle","Fonds selon la procédure","Matériel et délégations connus"],"narration":"Une caisse juste commence avant le premier client. Utilisez votre session personnelle, contrôlez le fonds selon la procédure et connaissez vos délégations. Ce cours ne fixe pas un montant de départ ou un seuil d’annulation universel. Les règles concrètes doivent être accessibles sur votre site."},{"heading":"Cas fictif : paiement incertain","lines":["Le terminal s’interrompt","Le client montre un écran","Ne pas répéter sans vérifier"],"narration":"Dans ce cas pédagogique fictif, une transaction semble interrompue et le client montre son téléphone. Ne prenez ni la capture ni l’interruption comme une conclusion suffisante. Vérifiez le statut dans le système prévu et demandez le relais avant de relancer. Répéter sans contrôle peut créer un double paiement."},{"heading":"La délégation protège la décision","lines":["Vérifier les faits","Respecter son rôle","Transmettre au bon relais"],"narration":"Une annulation ou un remboursement doit respecter votre délégation et la règle applicable. Si la décision dépasse votre rôle, transmettez les faits et attendez la validation prévue. N’utilisez jamais le code d’un collègue pour contourner cette étape. En cas de contestation, expliquez la vérification sans vous laisser pousser à une opération improvisée."},{"heading":"Clôturer avec les vrais chiffres","lines":["Comparer au théorique","Recompter et rechercher","Tracer sans accusation"],"narration":"En clôture, comparez le comptage réel au théorique. S’il y a un écart, recomptez et recherchez les éléments utiles. Gardez les valeurs réelles et transmettez selon la procédure. Un écart ne prouve pas à lui seul un vol. Modifier les nombres pour retrouver zéro cache le problème et empêche de comprendre."},{"heading":"Les personnes passent avant les fonds","lines":["Aucune confrontation","Consignes d’alerte du site","Accompagnement après incident"],"narration":"En cas de menace, préservez les personnes. Appliquez les consignes sans poursuivre un agresseur ni défendre les fonds au prix d’une exposition. Les dispositifs d’alerte doivent être connus et utilisés dans les conditions expliquées. Le retour à l’activité se prépare après la mise en sécurité et le relais nécessaire."},{"heading":"S’entraîner sans paiement réel","lines":["Simulation d’ouverture","Paiement fictif incertain","Clôture et transmission"],"narration":"Mettez la vidéo en pause et réalisez les deux cas du cours avec le responsable. Utilisez seulement un environnement d’entraînement et des données fictives. Aucun vrai client ne doit être débité pour apprendre. Le quiz final reprend les vérifications, la délégation, la traçabilité et la priorité donnée aux personnes."}]}}$program$::jsonb,$media${"key":"caisse","version":"2026-11-03","duration_seconds":116.858458,"size_bytes":1445413,"sha256":"582ec5c5cbed9a66a736fee2d9fab372981727c757599b7f8b67e5c2624ae8e9","width":1280,"height":720,"video_codec":"h264","audio_codec":"aac","narration":"synthetic","voice":"fr_FR-siwis-medium","voice_dataset_license":"CC-BY-4.0","voice_model_card":"https://huggingface.co/rhasspy/piper-voices/blob/main/fr/fr_FR/siwis/medium/MODEL_CARD","captions_burned_in":true,"caption_cues":34,"chapters":[{"title":"Préparer avant d’encaisser","seconds":0.0},{"title":"Cas fictif : paiement incertain","seconds":18.051},{"title":"La délégation protège la décision","seconds":37.262},{"title":"Clôturer avec les vrais chiffres","seconds":57.831},{"title":"Les personnes passent avant les fonds","seconds":77.32},{"title":"S’entraîner sans paiement réel","seconds":96.253}]}$media$::jsonb,'library/2026-11-03/caisse/582ec5c5cbed9a66a736fee2d9fab372981727c757599b7f8b67e5c2624ae8e9.mp4') on conflict(program_key,version) do nothing;
insert into opspilot_private.training_programs(program_key,version,payload,media_manifest,object_path) values('chaine-froid','2026-11-03',$program${"key":"chaine-froid","version":"2026-11-03","title":"Chaîne du froid : mesurer, comparer et décider","category":"Hygiène alimentaire","summary":"Contrôler le froid avec la bonne méthode et gérer un écart sans décider sur le seul afficheur.","audience":"Réception, réserve, rayon réfrigéré, préparation et service de denrées sensibles.","prerequisites":"Seuils validés du site et des produits, procédure de mesure, matériel de contrôle et relais responsable.","requirement":"role_required","applicability":"Instruction de maîtrise sanitaire pour les personnes exposant, recevant ou stockant des denrées sous température contrôlée. Les seuils varient selon les produits, étapes et textes applicables.","onsite":"Identifier les seuils réels, réaliser une mesure selon le protocole sans contaminer la denrée et simuler le signalement d’un écart. Le responsable valide l’usage de l’instrument et la décision.","objectives":["Retrouver le seuil applicable au produit et à l’étape contrôlée.","Distinguer température d’air, indication d’enceinte et mesure de denrée.","Isoler un écart et transmettre une information permettant une décision sûre."],"positioning":["Savez-vous où lire les seuils de vos produits ?","Pouvez-vous expliquer ce que mesure votre thermomètre ?","Savez-vous qui décide du devenir d’un lot en écart ?"],"reading_minutes":10,"activity_minutes":10,"sources":[{"label":"Ministère de l’Agriculture : chaîne du froid et températures par denrée","url":"https://agriculture.gouv.fr/securite-sanitaire-des-aliments-tout-sur-la-chaine-du-froid"}],"chapters":[{"title":"La température utile dépend du produit et de l’étape","body":"# Le froid ralentit ; il ne remet pas un compteur à zéro\nLe froid aide à maîtriser la multiplication de nombreux micro-organismes. Remettre un aliment au froid ne supprime pas automatiquement les conséquences d’une exposition précédente. La décision doit prendre en compte le produit, la température, la durée connue ou inconnue, l’emballage et les procédures validées. L’aspect et l’odeur ne suffisent pas à décider.\n\nIl n’existe pas un seuil unique « quatre degrés pour tout le frais » ni une tolérance automatique de réception valable pour tous les produits. Les exigences dépendent de la denrée et du stade. Retrouvez la consigne validée, l’information du fabricant et la règle applicable. Si elles semblent contradictoires ou absentes, demandez le relais plutôt que d’inventer une tolérance.\n\nCas pédagogique fictif : le camion affiche une température normale mais une caisse est restée à quai. L’afficheur ne prouve pas à lui seul la température de cette denrée ni son historique. Le contrôle de réception porte sur ce que prévoit le protocole : produit, intégrité, dates, mesure adaptée et délai de mise au froid.\n\nPréparez la réception pour limiter l’attente et la manutention inutile. Au stockage et à l’exposition, respectez les charges et la circulation d’air prévues par le fabricant de l’enceinte. Une porte ouverte, une surcharge ou une grille obstruée doit être corrigée selon la procédure sans masquer l’écart constaté."},{"title":"Mesurer puis gérer l’écart sans le dissimuler","body":"# Mesure, heure et contexte\nUn afficheur d’enceinte, un thermomètre infrarouge et une sonde ne donnent pas nécessairement la même information. Utilisez la méthode prévue pour le contrôle et l’appareil adapté, vérifié selon le plan du site. Protégez les denrées contre la contamination par l’instrument. Une mesure de surface peut être un repère, mais ne remplace pas toute mesure de produit exigée par le protocole.\n\nEnregistrez la valeur réelle avec l’heure, la référence du produit ou de l’enceinte et le contexte utile. Ne recopiez pas une valeur attendue pour compléter un tableau. Une donnée exacte permet de comprendre et de décider ; une valeur inventée cache le danger et empêche le suivi.\n\nSi un seuil est dépassé ou si l’historique manque, interrompez la mise à disposition concernée, isolez selon la procédure et alertez. Le responsable évalue et décide du devenir des denrées et du traitement de l’équipement. Ne concluez pas que toute denrée est sûre parce que l’enceinte revient à sa température de consigne. Ne détruisez pas non plus sans appliquer la décision prévue.\n\nAprès correction, la vérification porte sur la cause et sur les denrées concernées : intervention technique, conditions de reprise, contrôle et trace de décision. Le rétablissement de l’afficheur seul ne clôt pas automatiquement l’incident. Ce module ne fixe aucune décision de vente universelle à partir d’une seule valeur."},{"title":"Exercice : l’enceinte au-dessus du seuil du site","body":"# Cas pédagogique fictif — historique inconnu\nUne enceinte indique une valeur supérieure au seuil prévu pour les produits qu’elle contient. Vous ignorez depuis combien de temps l’écart dure. Le responsable n’a pas encore évalué les lots et aucune mesure complémentaire n’est réalisée.\n\nTravail demandé : écrivez les quatre premières informations utiles et les actions immédiates. Puis retrouvez sur le site le seuil de deux produits différents et faites une mesure encadrée avec la méthode prévue. Livrable : une fiche comportant heure, produit ou enceinte, valeur réelle, historique disponible, action de protection, relais et décision à compléter par la personne compétente.\n\nPiste de correction : ne pas remettre les produits à disposition sur une simple impression ; isoler selon la procédure ; transmettre la valeur et l’absence d’historique ; appliquer la décision du responsable puis vérifier la correction. « Le froid est revenu donc tout est bon » ignore l’exposition passée.\n\nCritères observés : bon seuil retrouvé, méthode de mesure adaptée, instrument utilisé sans contamination, valeur fidèle, décision réservée au relais prévu. Pour approfondir, comparez une mesure d’air et une mesure de denrée et expliquez pourquoi leur sens diffère. Le quiz final vérifie la logique de contrôle ; il ne prouve pas la réalisation des relevés réels du site."}],"quiz":[{"question":"Peut-on appliquer un seuil de +4 °C à tous les produits frais sans vérification ?","options":["Oui, toujours.","Non ; retrouver le seuil du produit et de l’étape.","Oui, si le camion est froid."],"question_type":"qcm_single","is_critical":false},{"question":"L’enceinte a dépassé son seuil pendant une durée inconnue. Que faire ?","options":["Remettre en vente dès que l’afficheur redevient normal.","Changer seulement le relevé.","Isoler selon la procédure, alerter et faire évaluer l’historique et les lots."],"question_type":"situation","is_critical":true},{"question":"Que doit contenir un relevé utile ?","options":["Valeur réelle, heure, produit ou enceinte et contexte prévu.","Une valeur copiée de la veille.","La température souhaitée."],"question_type":"qcm_single","is_critical":false},{"question":"Le camion affiche une valeur normale mais une caisse a attendu à quai. Quelle conclusion tirer ?","options":["La caisse est nécessairement conforme.","L’afficheur seul ne prouve pas l’état et l’historique de la denrée.","Le lot doit être automatiquement vendu avec remise."],"question_type":"situation","is_critical":false},{"question":"Remettre au froid efface-t-il automatiquement le risque d’une exposition passée ?","options":["Oui, si l’on attend une heure.","Oui, si le produit sent bon.","Non ; appliquer l’évaluation et la décision prévues."],"question_type":"critical","is_critical":true},{"question":"Quelle méthode de mesure utiliser ?","options":["Celle du protocole, avec un instrument adapté sans contaminer la denrée.","N’importe laquelle si elle donne une valeur basse.","Le toucher seulement."],"question_type":"qcm_single","is_critical":false}],"video":{"title":"La mesure n’est utile qu’avec la bonne décision","scenes":[{"heading":"Pas un seuil pour tout le frais","lines":["Quel produit ?","À quelle étape ?","Quelle consigne validée ?"],"narration":"Pour contrôler le froid, commencez par le produit et l’étape. Il n’existe pas un seuil unique valable pour toutes les denrées fraîches. Retrouvez la consigne validée, les indications du produit et la règle applicable. Si l’information manque, demandez une vérification ; n’inventez pas de tolérance."},{"heading":"Cas fictif : la caisse à quai","lines":["Camion : indication normale","Caisse : attente prolongée","Denrée : contrôle nécessaire"],"narration":"Dans ce cas pédagogique fictif, le camion affiche une température normale, mais une caisse est restée à quai. L’afficheur du camion ne prouve pas l’historique de cette caisse. Réalisez le contrôle prévu pour la denrée, son emballage, sa date et sa température, avec la méthode adaptée."},{"heading":"Savoir ce que l’on mesure","lines":["Air de l’enceinte","Surface du produit","Mesure prévue au protocole"],"narration":"Un afficheur, un appareil infrarouge et une sonde ne mesurent pas nécessairement la même chose. Utilisez l’instrument et la méthode prévus sans contaminer l’aliment. Notez la valeur réelle, l’heure et le contexte utile. Une valeur souhaitée ou copiée ne permet ni de surveiller ni de décider."},{"heading":"L’écart demande un relais","lines":["Limiter la mise à disposition","Isoler selon la procédure","Faire décider sur les données"],"narration":"Si le seuil est dépassé ou si la durée est inconnue, limitez la mise à disposition, isolez selon la procédure et alertez. Le responsable évalue les données et décide du devenir des denrées. Remettre au froid n’efface pas automatiquement l’exposition passée. Un afficheur revenu à la normale ne suffit pas à clôturer l’incident."},{"heading":"Exercice de contrôle réel","lines":["Retrouver deux seuils","Faire une mesure encadrée","Transmettre une fiche complète"],"narration":"Mettez la vidéo en pause. Retrouvez les seuils de deux produits de votre poste. Avec le responsable, réalisez une mesure selon le protocole et expliquez ce que l’appareil mesure. Complétez ensuite la fiche du cas écrit : valeur, heure, historique disponible, action immédiate et relais de décision."},{"heading":"Mesurer. Comparer. Suivre.","lines":["Une donnée fidèle","Une décision adaptée","Une correction vérifiée"],"narration":"La méthode tient en trois verbes : mesurer, comparer et suivre. Mesurer une donnée fidèle, la comparer au bon seuil et suivre la décision avec sa vérification. Le quiz final reprend ces choix ; les contrôles réels et la formation pratique du site restent nécessaires."}]}}$program$::jsonb,$media${"key":"chaine-froid","version":"2026-11-03","duration_seconds":116.607438,"size_bytes":1439945,"sha256":"929964251b8ab824a40cee4b18a74c8fd9bc3d6083f3fbf1ffb831e6c47b420c","width":1280,"height":720,"video_codec":"h264","audio_codec":"aac","narration":"synthetic","voice":"fr_FR-siwis-medium","voice_dataset_license":"CC-BY-4.0","voice_model_card":"https://huggingface.co/rhasspy/piper-voices/blob/main/fr/fr_FR/siwis/medium/MODEL_CARD","captions_burned_in":true,"caption_cues":44,"chapters":[{"title":"Pas un seuil pour tout le frais","seconds":0.0},{"title":"Cas fictif : la caisse à quai","seconds":19.802},{"title":"Savoir ce que l’on mesure","seconds":38.245},{"title":"L’écart demande un relais","seconds":58.025},{"title":"Exercice de contrôle réel","seconds":77.886},{"title":"Mesurer. Comparer. Suivre.","seconds":98.477}]}$media$::jsonb,'library/2026-11-03/chaine-froid/929964251b8ab824a40cee4b18a74c8fd9bc3d6083f3fbf1ffb831e6c47b420c.mp4') on conflict(program_key,version) do nothing;
insert into opspilot_private.training_programs(program_key,version,payload,media_manifest,object_path) values('dates-stocks','2026-11-03',$program${"key":"dates-stocks","version":"2026-11-03","title":"DLC, DDM et stocks : décider avant de réapprovisionner","category":"Hygiène alimentaire","summary":"Distinguer les dates, organiser la rotation et traiter une anomalie sans réétiqueter un produit retiré.","audience":"Équipes de réception, réserve, rayon alimentaire et préparation.","prerequisites":"Consignes de contrôle, conservation, ouverture et retrait propres aux produits du poste.","requirement":"role_required","applicability":"Compétences à intégrer aux instructions d’hygiène des personnes chargées des denrées et des stocks. La fréquence des contrôles est définie par les risques et la procédure du site.","onsite":"Contrôler un échantillon réel, lire les conditions après ouverture, organiser une rotation par dates et montrer la zone d’isolement. Aucun produit fictif ne doit être confondu avec un stock réel.","objectives":["Distinguer une DLC d’une DDM et une condition après ouverture.","Classer un stock par date pertinente plutôt que par seul ordre d’arrivée.","Isoler et tracer un produit non conforme sans prolonger sa date."],"positioning":["Reconnaissez-vous les deux mentions de date ?","Savez-vous quelle durée appliquer après ouverture ?","Pouvez-vous retrouver le lot et la décision d’un retrait ?"],"reading_minutes":10,"activity_minutes":10,"sources":[{"label":"DGCCRF : distinguer DLC et DDM","url":"https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/date-limite-de-consommation-et-date-de-durabilite-minimale-ce-que-vous-devez-savoir"},{"label":"Service Public : dates, conservation et responsabilité du vendeur","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F10990"}],"chapters":[{"title":"Lire la date avec les conditions du produit","body":"# Trois informations à rapprocher\nLa DLC est indiquée par « à consommer jusqu’au ». Lorsqu’elle est dépassée, la denrée ne doit plus être commercialisée. La DDM, annoncée par « à consommer de préférence avant », concerne la conservation de qualités attendues : son dépassement n’entraîne pas automatiquement un retrait, mais la sécurité et l’état du produit restent à vérifier selon la procédure. Une boîte bombée ou un emballage altéré ne devient pas acceptable parce que la DDM n’est pas dépassée.\n\nLa date doit être lue avec les conditions de conservation et les instructions après ouverture. Ouvrir un produit peut modifier sa durée d’utilisation. Étiquetez l’ouverture et la durée applicable selon la consigne validée ; n’utilisez pas une règle inventée « trois jours pour tout ». Si l’information manque, faites décider le responsable compétent avant utilisation.\n\nCas pédagogique fictif : un pot ouvert hier porte une DLC d’origine dans dix jours, mais le fabricant impose une durée plus courte après ouverture. La date lointaine ne permet pas d’ignorer cette instruction. Vérifiez ensemble date d’ouverture, conditions de conservation et limite applicable.\n\nL’apparence ou l’odeur ne suffisent pas à garantir la sécurité d’un produit. Le contrôle documentaire et les conditions réelles complètent l’observation. Pour un article non conforme, empêchez sa remise à disposition accidentelle et conservez les informations utiles au relais : référence, lot, date, quantité et anomalie."},{"title":"Faire sortir la bonne date et agir avant la perte","body":"# L’ordre d’arrivée n’est pas toujours l’ordre utile\nLe FIFO suit l’ordre d’entrée ; le FEFO privilégie l’échéance la plus proche. Pour des denrées à dates différentes, regarder seulement la livraison la plus ancienne peut laisser un lot plus urgent derrière. Comparez les dates pertinentes avant le réassort et maintenez la séparation ou l’identification nécessaires pour conserver la traçabilité.\n\nPréparez un réassort qui ne prolonge pas l’exposition hors des conditions de conservation. Faites remonter les quantités et dates courtes au responsable afin d’ajuster la commande ou les actions autorisées. Une remise, un don ou une transformation ne permet jamais d’ignorer la sécurité, les règles de conservation et le cadre applicable. Les pourcentages de remise et les échéances commerciales sont des décisions du site, pas des règles universelles du cours.\n\nUn retrait doit comporter une action physique et une trace utile. L’isolement empêche une remise en rayon ; l’enregistrement permet de comprendre ce qui a été retiré et la décision prise. Ne changez pas une étiquette pour prolonger la DLC et ne remettez pas en vente un produit retiré pour ce motif.\n\nAnalysez ensuite les causes possibles sans conclure trop vite : commande, rotation, réception, conditionnement, panne ou demande peuvent expliquer une perte. Un indicateur de démarque sert à chercher et vérifier, pas à désigner automatiquement un responsable. Le contrôle se fait à une fréquence adaptée au rayon et aux produits, définie dans la procédure du site."},{"title":"Exercice de classement et de retrait","body":"# Cas pédagogique fictif — trois lots\nAujourd’hui est le 3 novembre. Lot A : reçu le 1er, DLC au 7. Lot B : reçu le 2, DLC au 5. Lot C : retrouvé en rayon avec DLC au 2. Tous les produits sont fictifs et servent seulement au raisonnement.\n\nTravail demandé : classez ce qui peut être présenté en priorité selon les dates, indiquez le traitement du lot C puis rédigez une trace de retrait. Ajoutez les conditions de conservation à vérifier : la date seule ne suffit pas à décider de la sécurité. Livrable : un ordre de rotation, une action immédiate et une note comportant référence, lot, date, quantité, anomalie et relais.\n\nPiste de correction : pour les lots admissibles après contrôle, B précède A selon la logique des échéances. C est retiré et isolé, puis traité selon la procédure, sans réétiquetage de prolongation. Si les produits portent une durée après ouverture, il faut également l’intégrer.\n\nCritères observés sur place : dates comparées, conditions conservées pendant la manipulation, produit douteux séparé, trace exploitable. Pour approfondir, ajoutez une DDM dépassée sur un produit à emballage intact : expliquez pourquoi l’examen et la décision diffèrent du cas d’une DLC dépassée. Le responsable vérifie l’exercice réel ; le quiz final contrôle les distinctions et décisions essentielles."}],"quiz":[{"question":"Une DLC est dépassée. Quelle décision prendre ?","options":["Changer l’étiquette.","Retirer de la vente et isoler selon la procédure.","Accorder simplement une remise."],"question_type":"critical","is_critical":true},{"question":"Un lot reçu hier expire avant celui reçu avant-hier. Quel principe suit les échéances ?","options":["Toujours vendre le plus ancien reçu.","Ignorer les dates si l’emballage paraît normal.","FEFO : privilégier l’échéance la plus proche après les contrôles."],"question_type":"situation","is_critical":false},{"question":"Un produit ouvert porte une instruction après ouverture plus courte que sa date initiale. Que faire ?","options":["Tenir compte de l’ouverture, de l’instruction et des conditions réelles.","Suivre seulement la date initiale.","Appliquer trois jours à tous les produits."],"question_type":"situation","is_critical":false},{"question":"Une DDM dépassée rend-elle automatiquement le produit dangereux ?","options":["Oui, sans autre examen.","Non ; vérifier son état, sa sécurité et la procédure applicable.","Non ; aucune vérification n’est nécessaire."],"question_type":"qcm_single","is_critical":false},{"question":"Quelle trace de retrait est exploitable ?","options":["Quelques produits retirés.","Une photo sans référence.","Référence, lot, date, quantité, anomalie et décision selon le site."],"question_type":"qcm_single","is_critical":false},{"question":"Une remise autorise-t-elle la vente d’un produit retiré pour DLC dépassée ?","options":["Non.","Oui, si elle dépasse la moitié du prix.","Oui, si le client accepte oralement."],"question_type":"critical","is_critical":true}],"video":{"title":"La bonne date avant le bon emplacement","scenes":[{"heading":"Lire trois informations","lines":["Le type de date","Les conditions de conservation","La durée après ouverture"],"narration":"Avant de réapprovisionner, lisez le type de date, les conditions de conservation et l’instruction après ouverture. La date limite de consommation est une limite à ne pas dépasser pour commercialiser la denrée. La date de durabilité minimale n’a pas la même fonction, mais la sécurité et l’état du produit restent à vérifier."},{"heading":"Cas fictif : deux livraisons","lines":["Lot A reçu en premier","Lot B expire plus tôt","Comparer avant de ranger"],"narration":"Dans ce cas pédagogique fictif, le lot A est arrivé avant le lot B. Pourtant, B expire plus tôt. Si les produits sont admissibles après contrôle, la rotation par échéance place B en priorité. C’est la logique du FEFO. L’ordre d’arrivée, à lui seul, ne suffit pas pour organiser tous les produits alimentaires."},{"heading":"L’ouverture peut changer la limite","lines":["Identifier l’ouverture","Lire la consigne du produit","Ne pas inventer une durée"],"narration":"Un pot ouvert peut avoir une durée d’utilisation plus courte que sa date initiale. Retenez l’ouverture, la consigne applicable et les conditions de conservation. Il n’existe pas dans ce cours une règle de trois jours valable pour tout. Quand une information manque, demandez une décision avant de continuer."},{"heading":"Retirer : séparer et tracer","lines":["Empêcher la remise en rayon","Identifier le lot et le motif","Appliquer la décision prévue"],"narration":"Un produit retrouvé après sa DLC doit être retiré de la vente et isolé selon la procédure. La trace précise le produit, le lot, la date, la quantité et le motif. Ne prolongez pas sa date avec une nouvelle étiquette. Une remise ne rend pas cette vente acceptable."},{"heading":"À vous de classer les lots","lines":["Comparer les échéances","Vérifier la conservation","Expliquer votre décision"],"narration":"Mettez la vidéo en pause et classez les trois lots du cours écrit. Justifiez la rotation des lots admissibles et le traitement du lot dépassé. Ensuite, faites le même repérage sur un échantillon réel avec le responsable, sans laisser les produits hors de leurs conditions de conservation."},{"heading":"Prévenir sans raccourci","lines":["Anticiper les dates courtes","Adapter les quantités","Ne pas contourner la sécurité"],"narration":"Anticiper les dates courtes permet de revoir les quantités et les actions autorisées. Promotions, dons ou transformations restent encadrés et ne contournent pas la sécurité des aliments. Le quiz final vérifiera votre capacité à distinguer les dates et à choisir une action de retrait et de suivi."}]}}$program$::jsonb,$media${"key":"dates-stocks","version":"2026-11-03","duration_seconds":113.045442,"size_bytes":1394616,"sha256":"0fc60f02ae8c3c3ebf005a5f365903d52204c0ddaf2669816197bdf102d58ebe","width":1280,"height":720,"video_codec":"h264","audio_codec":"aac","narration":"synthetic","voice":"fr_FR-siwis-medium","voice_dataset_license":"CC-BY-4.0","voice_model_card":"https://huggingface.co/rhasspy/piper-voices/blob/main/fr/fr_FR/siwis/medium/MODEL_CARD","captions_burned_in":true,"caption_cues":40,"chapters":[{"title":"Lire trois informations","seconds":0.0},{"title":"Cas fictif : deux livraisons","seconds":19.652},{"title":"L’ouverture peut changer la limite","seconds":40.73},{"title":"Retirer : séparer et tracer","seconds":60.301},{"title":"À vous de classer les lots","seconds":78.466},{"title":"Prévenir sans raccourci","seconds":95.773}]}$media$::jsonb,'library/2026-11-03/dates-stocks/0fc60f02ae8c3c3ebf005a5f365903d52204c0ddaf2669816197bdf102d58ebe.mp4') on conflict(program_key,version) do nothing;
insert into opspilot_private.training_programs(program_key,version,payload,media_manifest,object_path) values('hygiene-alimentaire','2026-11-03',$program${"key":"hygiene-alimentaire","version":"2026-11-03","title":"Hygiène alimentaire au poste : prévenir les contaminations","category":"Hygiène alimentaire","summary":"Séparer les usages, appliquer le nettoyage prévu, vérifier les allergènes et isoler une denrée douteuse.","audience":"Personnes manipulant ou servant des denrées en commerce alimentaire et restauration.","prerequisites":"Plan de maîtrise sanitaire et consignes du poste disponibles ; accès à la composition des produits et au relais responsable.","requirement":"internal_required","applicability":"Instructions et formation à l’hygiène adaptées aux manipulations réellement effectuées. Ce parcours interne ne remplace pas la formation spécifique distincte exigible dans certaines activités de restauration.","onsite":"Démontrer le lavage des mains et la séparation cru/prêt à consommer ; appliquer le protocole de nettoyage avec le matériel réel ; retrouver une information écrite sur un allergène. Le responsable observe et corrige.","objectives":["Repérer une contamination possible et interrompre le transfert.","Appliquer les étapes et paramètres du nettoyage prévus au poste.","Retrouver une information fiable sur les allergènes et traiter une incertitude sans promettre."],"positioning":["Savez-vous distinguer nettoyer et désinfecter ?","Pouvez-vous retrouver la composition actuelle d’un produit ?","Savez-vous où isoler une denrée douteuse et qui alerter ?"],"reading_minutes":12,"activity_minutes":12,"sources":[{"label":"Ministère de l’Agriculture : obligations de formation à l’hygiène, 16 juillet 2026","url":"https://agriculture.gouv.fr/restauration-quelles-obligations-en-matiere-de-formation-a-lhygiene-des-aliments"},{"label":"Ministère de l’Agriculture : contrôles et bonnes pratiques en restauration","url":"https://agriculture.gouv.fr/la-securite-sanitaire-de-lalimentation-que-controle-t-dans-un-restaurant"},{"label":"Service Public : information écrite sur les allergènes","url":"https://www.service-public.gouv.fr/particuliers/vosdroits/F32192"}],"chapters":[{"title":"Interrompre les transferts au bon moment","body":"# Un aliment peut être contaminé sans signe visible\nLes dangers peuvent être microbiologiques, chimiques, physiques ou liés aux allergènes. Un aliment apparemment normal n’est pas une preuve d’absence de danger. Les procédures de maîtrise sanitaire traduisent l’analyse des risques de l’activité en gestes, contrôles et actions à appliquer. Toutes les étapes ne sont pas automatiquement des points critiques HACCP : suivez les points réellement définis dans le plan du site.\n\nUne contamination croisée est un transfert par les mains, un outil, une surface, un emballage ou un aliment. Cas pédagogique fictif : après une préparation crue, un couteau est utilisé pour couper un produit prêt à consommer. Arrêtez la tâche, prévenez le responsable et appliquez le traitement prévu pour l’outil, la surface et les aliments potentiellement exposés. Nettoyer seulement le couteau après coup ne rend pas automatiquement sûres les denrées déjà touchées.\n\nRespectez la séparation des usages et l’organisation dans l’espace ou dans le temps, avec le nettoyage prévu entre tâches. Des couleurs de planches peuvent aider si le site les utilise, mais aucun code couleur ne garantit la propreté d’un outil. Le lavage des mains se réalise aux moments prévus et avec la technique du site ; les gants ne le remplacent pas.\n\nPortez une tenue adaptée, protégez les blessures selon les consignes et signalez au relais prévu les symptômes susceptibles d’affecter la sécurité des denrées. Les informations de santé se traitent avec discrétion. N’improvisez pas seul une adaptation d’un poste alimentaire."},{"title":"Nettoyer avec méthode et informer sans deviner","body":"# Les paramètres ne se compensent pas au hasard\nNettoyer retire des salissures ; désinfecter vise à réduire les micro-organismes selon un protocole adapté. Le plan du site précise la surface, le produit, le dosage, les étapes, le temps de contact, le rinçage lorsqu’il est requis et la fréquence. Un produit combiné peut avoir une procédure spécifique : suivez son usage prévu. N’augmentez pas la concentration ou la température pour compenser un temps de contact raccourci.\n\nPréparez la zone et protégez les denrées contre les projections et les résidus. Utilisez les protections prévues, ne mélangez pas les produits et vérifiez le résultat avec les moyens du site. Consignez le contrôle demandé et signalez une anomalie. Une trace aide à démontrer et à vérifier les actions ; l’absence de signature n’est pas, à elle seule, la preuve universelle qu’aucun nettoyage n’a eu lieu.\n\nPour un allergène, consultez la composition actuelle, la fiche fournisseur ou le support écrit prévu pour le client. Une recette habituelle ou la mémoire d’un collègue ne suffit pas si un ingrédient a changé. Vérifiez aussi les risques de contact croisé selon la procédure. Ne promettez jamais « sans allergène » sur une simple impression.\n\nSi l’information manque, dites que vous devez vérifier et sollicitez le responsable avant de servir ou de répondre définitivement. L’information écrite accessible au client ne se remplace pas par une assurance orale approximative. Signalez également toute trace de nuisibles et appliquez les mesures prévues, sans déplacer au hasard un dispositif de lutte."},{"title":"Exercice : un ustensile partagé et une recette modifiée","body":"# Deux cas pédagogiques fictifs\nCas 1 : une pince ayant servi à une denrée crue est posée près de produits prêts à consommer. Vous ne savez pas ce qu’elle a touché. Cas 2 : une cliente demande si une sauce contient du lait ; la recette fournisseur vient de changer et la fiche affichée n’est pas datée.\n\nTravail demandé : pour chaque cas, notez le risque, l’action immédiate, l’information à vérifier et le relais. Retrouvez ensuite sur place le protocole de nettoyage et une fiche d’allergènes actuelle. Livrable : deux décisions justifiées et une démonstration de nettoyage encadrée, sans exposer des aliments pendant l’exercice.\n\nCritères de réussite : ne pas remettre un aliment douteux à disposition sur la seule base de son aspect ; distinguer le traitement de l’outil de celui des denrées exposées ; respecter les paramètres du produit ; ne pas inventer la composition d’une recette.\n\nPistes de correction : dans le premier cas, interrompre l’usage, isoler ce qui peut être concerné, alerter puis appliquer la décision de maîtrise sanitaire. Dans le second, consulter une composition fiable et actuelle, faire corriger le support écrit si nécessaire et informer le client avec une donnée vérifiée. S’il reste une incertitude, ne pas garantir l’absence d’un allergène.\n\nLe responsable vérifie les gestes au poste. Si une difficulté persiste, revoir la démonstration avant de reprendre seul. Le quiz final mesure la compréhension de ces décisions, pas la conformité sanitaire globale de l’établissement."}],"quiz":[{"question":"Un couteau passe du cru à un produit prêt à consommer sans traitement prévu. Que faire ?","options":["Essuyer la lame puis poursuivre.","Arrêter et traiter l’outil ainsi que les denrées potentiellement exposées selon la procédure.","Attendre un changement visible du produit."],"question_type":"situation","is_critical":true},{"question":"La recette fournisseur change et un client demande les allergènes. Quelle réponse retenir ?","options":["Répondre de mémoire.","Garantir l’absence si rien n’est visible.","Vérifier une composition actuelle et le support écrit, puis répondre sans inventer."],"question_type":"situation","is_critical":true},{"question":"Peut-on raccourcir le temps de contact en augmentant la dose d’un produit ?","options":["Non ; respecter le protocole et les paramètres prévus.","Oui, à volonté.","Oui, si la surface paraît propre."],"question_type":"qcm_single","is_critical":false},{"question":"Les gants remplacent-ils le lavage des mains ?","options":["Oui, toute la journée.","Non ; appliquer les règles d’hygiène prévues et changer de tâche avec précaution.","Oui, s’ils sont transparents."],"question_type":"qcm_single","is_critical":false},{"question":"Un aliment d’aspect normal est-il nécessairement sans danger ?","options":["Oui, s’il sent bon.","Oui, s’il est froid.","Non ; l’aspect ne remplace pas les contrôles et conditions de conservation."],"question_type":"qcm_single","is_critical":false},{"question":"À quoi sert l’enregistrement d’une action d’hygiène ?","options":["À permettre son suivi et sa vérification, avec les autres éléments utiles.","À rendre automatiquement toute denrée sûre.","À remplacer le geste réel."],"question_type":"qcm_single","is_critical":false}],"video":{"title":"L’hygiène se décide à chaque changement de tâche","scenes":[{"heading":"Un transfert peut rester invisible","lines":["Mains et ustensiles","Surfaces et emballages","Denrées et allergènes"],"narration":"La sécurité alimentaire ne se juge pas seulement à l’aspect d’un produit. Un danger peut se transférer par les mains, les ustensiles, une surface ou un emballage. Le cours interne sert à appliquer les consignes de votre activité. Il ne transforme pas chaque geste en point critique : suivez le plan de maîtrise sanitaire du site."},{"heading":"Cas fictif : le couteau partagé","lines":["Un usage cru","Puis un aliment prêt à consommer","Un transfert à interrompre"],"narration":"Dans ce cas pédagogique fictif, le même couteau passe d’une préparation crue à un aliment prêt à consommer. Il faut arrêter et prévenir le responsable. Le traitement concerne l’outil et les aliments potentiellement exposés. Nettoyer le couteau après coup ne rend pas automatiquement sûres les denrées qu’il a déjà touchées."},{"heading":"Le protocole fait la différence","lines":["Produit et dosage prévus","Étapes et temps respectés","Contrôle puis trace utile"],"narration":"Nettoyer et désinfecter ont des objectifs différents. Suivez le protocole réel : produit, dose, étapes, temps de contact et rinçage s’il est prescrit. Ne mélangez pas les produits et ne compensez pas un temps trop court en augmentant la concentration. Vérifiez le résultat et consignez ce qui est demandé."},{"heading":"Allergènes : vérifier avant de dire","lines":["Composition actuelle","Information écrite disponible","Aucune promesse improvisée"],"narration":"Une cliente demande si la sauce contient du lait. La recette vient de changer. Ne répondez pas de mémoire. Consultez une information actuelle et fiable, vérifiez le support écrit et les risques de contact croisé selon la procédure. Si l’information manque, demandez le relais avant de garantir quoi que ce soit."},{"heading":"À pratiquer au poste","lines":["Lavage des mains","Séparation des usages","Recherche d’une fiche allergènes"],"narration":"Mettez la vidéo en pause. Avec le responsable, montrez le lavage des mains prévu, le changement d’ustensile entre deux usages et l’endroit où vérifier une composition. Réalisez ensuite le nettoyage encadré. Les gants et les couleurs des planches ne remplacent ni l’hygiène des mains ni le traitement nécessaire du matériel."},{"heading":"Ne pas deviner face au doute","lines":["Interrompre l’exposition","Isoler selon la procédure","Faire décider et tracer"],"narration":"Face à une denrée douteuse, interrompez l’exposition, isolez selon la procédure et alertez le responsable. La trace facilite le suivi, mais ne remplace pas l’action réelle. Reprenez les cas du cours écrit puis le quiz. Le responsable doit encore observer les gestes alimentaires propres à votre poste."}]}}$program$::jsonb,$media${"key":"hygiene-alimentaire","version":"2026-11-03","duration_seconds":119.55746,"size_bytes":1456723,"sha256":"c99b26ce980b487b59b9f16a58776b02bbae65d9129681806836c8f53a7b5ed6","width":1280,"height":720,"video_codec":"h264","audio_codec":"aac","narration":"synthetic","voice":"fr_FR-siwis-medium","voice_dataset_license":"CC-BY-4.0","voice_model_card":"https://huggingface.co/rhasspy/piper-voices/blob/main/fr/fr_FR/siwis/medium/MODEL_CARD","captions_burned_in":true,"caption_cues":42,"chapters":[{"title":"Un transfert peut rester invisible","seconds":0.0},{"title":"Cas fictif : le couteau partagé","seconds":19.756},{"title":"Le protocole fait la différence","seconds":39.165},{"title":"Allergènes : vérifier avant de dire","seconds":59.663},{"title":"À pratiquer au poste","seconds":79.198},{"title":"Ne pas deviner face au doute","seconds":100.034}]}$media$::jsonb,'library/2026-11-03/hygiene-alimentaire/c99b26ce980b487b59b9f16a58776b02bbae65d9129681806836c8f53a7b5ed6.mp4') on conflict(program_key,version) do nothing;
insert into opspilot_private.training_programs(program_key,version,payload,media_manifest,object_path) values('incendie-evacuation','2026-11-03',$program${"key":"incendie-evacuation","version":"2026-11-03","title":"Incendie et évacuation : appliquer les consignes du site","category":"Sécurité au travail","summary":"Reconnaître l’alerte, rejoindre le point prévu et transmettre les informations sans se réexposer.","audience":"Personnel des magasins et restaurants, selon l’organisation de sécurité de l’établissement.","prerequisites":"Consignes incendie et plan du site disponibles ; responsable pour la visite et l’exercice réel.","requirement":"internal_required","applicability":"Information et entraînement adaptés aux consignes, à l’effectif et aux risques du site. La périodicité des exercices dépend du cadre applicable ; aucun renouvellement universel n’est fixé par l’app.","onsite":"Visite des dégagements et du point de rassemblement ; exercice d’évacuation organisé et observé, avec prise en compte des visiteurs et des besoins d’assistance. La manipulation d’un extincteur exige une démonstration et un entraînement adaptés.","objectives":["Identifier le signal d’alarme et le cheminement d’évacuation prévu.","Choisir un comportement qui évite la réexposition et le retour dans les locaux.","Transmettre une absence ou une difficulté au responsable de rassemblement."],"positioning":["Reconnaissez-vous le signal d’évacuation du site ?","Savez-vous quel point rejoindre et qui le coordonne ?","Connaissez-vous la procédure d’assistance et votre rôle ?"],"reading_minutes":9,"activity_minutes":10,"sources":[{"label":"Code du travail, R4227-34 à R4227-39 : alarme, consignes et exercices","url":"https://www.legifrance.gouv.fr/codes/section_lc/LEGITEXT000006072050/LEGISCTA000018489063/"}],"chapters":[{"title":"Se préparer avant l’alarme","body":"# L’itinéraire s’apprend avant l’urgence\nRepérez le signal d’alarme, le moyen d’alerter, les sorties utilisables depuis votre poste et le point de rassemblement. Les consignes du site précisent les fonctions d’évacuation et le dispositif d’assistance. Ne vous attribuez pas un rôle de guide, de serre-file ou d’intervention sans qu’il vous soit confié et expliqué.\n\nUn dégagement doit rester praticable. Signalez une porte bloquée, une sortie masquée ou un stockage gênant. Ne neutralisez pas une porte coupe-feu pour faciliter un passage. Une bonne préparation consiste aussi à connaître une autre issue utilisable si le chemin habituel est impraticable, selon la configuration réelle.\n\nCas pédagogique fictif : un salarié rejoint une réserve éloignée pour prendre un vêtement dès que l’alarme retentit. Ce détour l’éloigne du trajet prévu et retarde la connaissance des personnes évacuées. L’urgence ne laisse pas le temps de récupérer des objets. Rejoignez le cheminement sûr prévu par les consignes et les personnes chargées de l’évacuation.\n\nDemandez comment sont accompagnés les clients, visiteurs et personnes ayant besoin d’assistance. Le dispositif doit être expliqué avant une situation réelle. Ne supposez pas qu’un collègue vous suivra, ni qu’il peut emprunter un escalier ou entendre le signal sans adaptation. Ce module prépare la compréhension ; le responsable organise la visite et l’exercice dans les locaux."},{"title":"Évacuer sans revenir ni intervenir au hasard","body":"# Le départ de feu n’est pas un exercice improvisé\nÀ l’alarme ou sur instruction d’évacuation, appliquez les consignes du site, quittez les locaux par une issue sûre et rejoignez le point prévu. N’utilisez pas un ascenseur ordinaire. N’empruntez pas un passage enfumé ; signalez immédiatement que le trajet prévu est impraticable et suivez les instructions d’urgence adaptées à votre position.\n\nSi vous découvrez un feu, donnez l’alerte selon l’organisation du site et préservez une possibilité de retrait. L’utilisation d’un extincteur dépend de la situation, des consignes et de l’entraînement reçu. Ne vous approchez pas des fumées et ne retardez pas l’alerte pour essayer seul d’éteindre. Un quiz ne vous entraîne pas à choisir et à manipuler un appareil.\n\nAu point de rassemblement, présentez-vous au relais prévu et signalez une personne manquante, sa dernière localisation connue ou un besoin d’assistance. Ne retournez pas la chercher dans le bâtiment. Une information précise permet aux personnes compétentes d’organiser la réponse sans ajouter une victime.\n\nAttendez l’autorisation de retour de la personne compétente prévue par l’organisation des secours. L’arrêt du signal sonore ou l’apparence calme des lieux ne constitue pas une autorisation. Après l’exercice, participez au retour d’expérience : trajet encombré, signal mal perçu, point de rassemblement inadapté ou problème d’assistance sont des faits utiles à corriger."},{"title":"Faire l’exercice et corriger les écarts","body":"# Mise en pratique organisée\nLe responsable prépare l’exercice selon les règles applicables au site. Ne déclenchez pas seul une alarme ni un appel aux secours pour vous entraîner. La consigne doit permettre de distinguer l’organisation de l’exercice d’une situation réelle, tout en observant les comportements nécessaires.\n\nTravail demandé : montrez votre trajet et l’issue alternative prévue ; expliquez ce que vous faites au point de rassemblement ; indiquez comment transmettre une difficulté. Livrable : trois observations factuelles et une action d’amélioration avec un responsable. Le temps d’évacuation peut être relevé par l’organisateur, mais l’app n’invente pas de résultat ni de délai garanti.\n\nCas pédagogique fictif : au rassemblement, une collègue manque et vous l’avez vue près d’une réserve. Réponse attendue : transmettre cette localisation au relais de sécurité et rester disponible au point prévu. Retourner dans les locaux constituerait une nouvelle exposition.\n\nCritères observés : absence de détour pour des affaires ; trajet sûr et consignes respectés ; assistance conforme au rôle confié ; remontée d’une absence sans retour en arrière. Si une difficulté est constatée, le responsable adapte les consignes puis organise une nouvelle vérification. Le quiz final permet de reprendre les décisions essentielles ; il ne valide ni un exercice réel, ni l’aptitude à manipuler tous les extincteurs."}],"quiz":[{"question":"L’alarme retentit. Votre veste est dans la réserve. Que faire ?","options":["La récupérer rapidement.","Évacuer sans détour selon les consignes.","Attendre un collègue avant toute décision."],"question_type":"situation","is_critical":true},{"question":"Au rassemblement, une collègue manque. Vous connaissez sa dernière localisation. Que faire ?","options":["Retourner la chercher.","Ne rien dire pour éviter l’inquiétude.","Transmettre la localisation au relais prévu sans rentrer."],"question_type":"situation","is_critical":true},{"question":"L’alarme s’arrête. Pouvez-vous reprendre votre poste immédiatement ?","options":["Non ; attendre l’autorisation de retour prévue.","Oui, le silence suffit.","Oui, si un client le demande."],"question_type":"qcm_single","is_critical":false},{"question":"Quelle préparation est nécessaire pour aider une personne ayant besoin d’assistance ?","options":["Inventer une méthode pendant l’urgence.","Connaître le dispositif et le rôle expliqués par le site.","Supposer qu’elle suit le groupe."],"question_type":"qcm_single","is_critical":false},{"question":"Quelle affirmation sur l’extincteur est juste ?","options":["Le quiz permet de l’utiliser dans toute situation.","Il faut toujours attaquer le feu seul.","Son usage exige des consignes et un entraînement adaptés sans retarder l’alerte."],"question_type":"qcm_single","is_critical":false},{"question":"Que faire face à une sortie encombrée avant toute urgence ?","options":["Signaler et faire rétablir le dégagement selon la procédure.","Attendre le prochain exercice.","Masquer la signalisation."],"question_type":"qcm_single","is_critical":false}],"video":{"title":"Évacuer : connaître le chemin, rester dehors","scenes":[{"heading":"Le chemin s’apprend avant","lines":["Reconnaître le signal","Repérer les issues","Connaître le rassemblement"],"narration":"Une évacuation commence avant l’alarme. Vous devez connaître le signal du site, les issues utilisables et le point de rassemblement. Demandez aussi quel relais coordonne l’évacuation et quel dispositif d’assistance est prévu. Une vidéo générale ne peut pas deviner le plan de votre établissement."},{"heading":"Cas fictif : la veste oubliée","lines":["L’alarme retentit","La veste reste en réserve","Aucun détour pour la reprendre"],"narration":"Dans ce cas pédagogique fictif, l’alarme retentit alors que votre veste est dans la réserve. Faut-il la récupérer ? Non. Le détour vous éloigne du trajet prévu et retarde le rassemblement. Appliquez les consignes, empruntez une issue sûre et laissez les objets personnels. N’utilisez pas un ascenseur ordinaire."},{"heading":"Un trajet doit rester sûr","lines":["Ne pas entrer dans les fumées","Suivre l’organisation du site","Signaler une issue impraticable"],"narration":"Si le trajet est enfumé ou impraticable, ne vous y engagez pas. Signalez la difficulté et appliquez les instructions adaptées à votre position. Les itinéraires et les solutions d’assistance doivent avoir été expliqués sur place. Prévenir un suraccident reste prioritaire, même quand on veut aider vite."},{"heading":"Une absence : transmettre","lines":["Dernier lieu connu","Relais de sécurité","Aucun retour dans le bâtiment"],"narration":"Au rassemblement, une collègue manque. Vous l’aviez vue près de la réserve. Transmettez cette information au relais de sécurité. Ne retournez pas la chercher. Les secours ont besoin d’un lieu précis, pas d’une nouvelle personne exposée. Attendez l’autorisation de retour prévue, même si le signal sonore s’arrête."},{"heading":"L’extincteur ne s’improvise pas","lines":["Alerter sans attendre","Préserver son retrait","S’entraîner avec encadrement"],"narration":"Un départ de feu n’est pas l’occasion de tester seul un extincteur. Alertez, gardez une possibilité de retrait et suivez les consignes. La manipulation exige un entraînement adapté et ne doit pas retarder l’évacuation. La réussite d’un quiz ne prouve pas que ce geste a été pratiqué."},{"heading":"À vérifier lors de l’exercice","lines":["Trajet dégagé","Signal compris","Rassemblement et assistance"],"narration":"Mettez la vidéo en pause et montrez votre trajet avec le responsable. Lors de l’exercice organisé, relevez ce qui facilite ou gêne l’évacuation. Un signal mal compris ou une porte bloquée mérite une correction concrète. Le cours écrit et le quiz vous aident à retenir les décisions ; l’exercice réel reste indispensable pour vérifier l’organisation."}]}}$program$::jsonb,$media${"key":"incendie-evacuation","version":"2026-11-03","duration_seconds":118.897415,"size_bytes":1505600,"sha256":"968b22d7c7cb319322f9f013c6827e883586745e98847d7e5aeae8f38c335d62","width":1280,"height":720,"video_codec":"h264","audio_codec":"aac","narration":"synthetic","voice":"fr_FR-siwis-medium","voice_dataset_license":"CC-BY-4.0","voice_model_card":"https://huggingface.co/rhasspy/piper-voices/blob/main/fr/fr_FR/siwis/medium/MODEL_CARD","captions_burned_in":true,"caption_cues":39,"chapters":[{"title":"Le chemin s’apprend avant","seconds":0.0},{"title":"Cas fictif : la veste oubliée","seconds":18.341},{"title":"Un trajet doit rester sûr","seconds":39.234},{"title":"Une absence : transmettre","seconds":59.455},{"title":"L’extincteur ne s’improvise pas","seconds":78.804},{"title":"À vérifier lors de l’exercice","seconds":96.61}]}$media$::jsonb,'library/2026-11-03/incendie-evacuation/968b22d7c7cb319322f9f013c6827e883586745e98847d7e5aeae8f38c335d62.mp4') on conflict(program_key,version) do nothing;
insert into opspilot_private.training_programs(program_key,version,payload,media_manifest,object_path) values('management','2026-11-03',$program${"key":"management","version":"2026-11-03","title":"Management de proximité : donner les moyens et suivre","category":"Management","summary":"Clarifier une mission, observer les difficultés et vérifier une amélioration sans réduire le travail à un indicateur.","audience":"Managers et responsables d’équipe du commerce et de la restauration.","prerequisites":"Connaître les rôles, procédures, relais RH et règles de planification applicables à l’établissement.","requirement":"professional","applicability":"Parcours de professionnalisation du management. Les obligations de l’employeur restent à examiner selon l’activité et ne sont pas remplacées par ce module.","onsite":"Préparer et observer un brief réel, faire reformuler une délégation et vérifier une action avec l’équipe. Choisir un cas sans données personnelles sensibles et recueillir le retour de l’apprenant.","objectives":["Formuler une mission avec résultat attendu, moyens, limites et point de suivi.","Conduire un échange fondé sur des faits et l’analyse de l’activité réelle.","Vérifier une action corrective avec des éléments observables et un retour de l’équipe."],"positioning":["Une personne peut-elle reformuler ce qui est attendu après votre brief ?","Savez-vous distinguer résultat insuffisant et moyen manquant ?","Votre suivi vérifie-t-il la correction et ses effets sur l’équipe ?"],"reading_minutes":11,"activity_minutes":12,"sources":[],"chapters":[{"title":"Une mission réalisable et comprise","body":"# Déléguer avec les moyens, pas seulement une consigne\nUne délégation utile décrit le résultat attendu, les moyens disponibles, les limites de décision et le moment de suivi. Faire reformuler permet de vérifier la compréhension sans transformer l’échange en contrôle de mémoire. Une tâche nouvelle nécessite une démonstration et une autonomie adaptée à la compétence observée, pas à une impression générale.\n\nCas pédagogique fictif : « Faites mieux sur les dates » n’indique ni priorité ni moyen. Une consigne exploitable peut préciser le rayon, la vérification à réaliser, la procédure de retrait, le relais en cas d’écart et un point après le contrôle. L’objectif ne doit jamais pousser à masquer une anomalie pour obtenir un indicateur favorable.\n\nUn brief court prépare l’activité : priorité, risque important, répartition et possibilité de demander de l’aide. Sa durée est choisie selon le contexte ; cinq minutes n’est pas une obligation ni une garantie d’efficacité. Demandez ce qui manque pour réaliser la tâche, notamment une information, un matériel ou une disponibilité.\n\nLa planification tient compte de la charge, des compétences et des règles applicables. Délais de prévenance, repos et modifications d’horaires doivent être vérifiés avec les textes et accords de l’établissement ainsi que le relais RH. Ce cours ne fixe pas un délai universel d’affichage du planning. En cas d’absence, réorganisez les priorités sans confier un poste dangereux à une personne non formée."},{"title":"Écouter les faits, traiter les difficultés et suivre","body":"# Observer l’activité avant de conclure\nUn résultat insuffisant peut avoir plusieurs causes : consigne imprécise, manque de compétence, charge, matériel, information ou organisation. Décrivez les faits observables puis demandez comment le travail s’est déroulé. Une règle de pourcentage de temps de parole ne garantit pas une écoute de qualité. Vérifiez la compréhension et construisez une action réalisable.\n\nUn désaccord courant peut se traiter dans un échange cadré, avec les personnes concernées et un suivi. En revanche, un signalement de violence, harcèlement ou discrimination ne doit pas être réduit à une médiation obligatoire entre les personnes. Protégez, recueillez les faits avec discrétion et sollicitez les relais prévus. N’organisez pas automatiquement une confrontation commune.\n\nPour une action corrective, fixez un responsable, une échéance réaliste, les moyens et ce qui permettra de vérifier l’effet. Un indicateur peut signaler un problème sans en prouver la cause. Comparez avec des observations de terrain et le retour de l’équipe. Une baisse des retraits ne prouve pas à elle seule une meilleure gestion si des produits ne sont plus contrôlés.\n\nLe suivi porte aussi sur l’appropriation : la personne sait-elle expliquer et réaliser la tâche ? Quel obstacle reste présent ? Tracez les décisions et les besoins utiles, sans enregistrer des détails sensibles dans un compte rendu collectif. Reconnaissez les progrès d’une manière adaptée à la personne et au contexte ; une valorisation publique n’est pas toujours souhaitée."},{"title":"Exercice : transformer un écart en action vérifiée","body":"# Cas pédagogique fictif — retraits répétés\nUn rayon connaît plusieurs retraits pour dates dépassées. Un responsable propose seulement de demander à l’équipe d’aller plus vite. On ne sait pas encore si la cause vient des commandes, de l’ordre de rangement, du temps disponible ou d’une consigne mal comprise.\n\nTravail demandé : rédigez un brief de quatre points et trois questions d’analyse du travail. Proposez une action avec responsable, moyens, échéance et preuve d’effet. Livrable : une fiche d’action d’une page et une reformulation par un collègue. Les chiffres ou délais choisis pour l’exercice doivent être indiqués comme fictifs.\n\nPiste de correction : observer le rangement et le contrôle, demander comment les dates sont comparées et vérifier les moyens. Tester une rotation par échéance sur le périmètre défini puis contrôler l’absence de produits dépassés et recueillir le retour de l’équipe. La réussite ne se réduit pas à une baisse de démarque ; elle doit conserver les contrôles et la sécurité alimentaire.\n\nCritères observés : faits séparés des jugements, objectif compréhensible, moyens disponibles, relais connu, vérification planifiée. Pour approfondir, introduisez une absence : quelle priorité peut être reportée sans créer de risque ni méconnaître une règle ? Le quiz final vérifie la méthode ; il n’évalue pas à lui seul la compétence globale d’un manager ni la conformité RH de l’établissement."}],"quiz":[{"question":"Quelle délégation est la plus utile ?","options":["Faites mieux.","Un résultat attendu, des moyens, des limites de décision et un point de suivi.","Un chiffre sans explication."],"question_type":"qcm_single","is_critical":false},{"question":"Des retraits se répètent. Que faire avant de conclure à un manque d’effort ?","options":["Exiger seulement plus de vitesse.","Supprimer le contrôle.","Observer la tâche et analyser consignes, charge, compétences et moyens."],"question_type":"situation","is_critical":false},{"question":"Un signalement de harcèlement est formulé. Quelle réponse éviter ?","options":["Imposer automatiquement une confrontation commune comme simple conflit.","Protéger et utiliser les relais prévus.","Traiter les faits avec discrétion."],"question_type":"critical","is_critical":true},{"question":"Une action est déclarée terminée. Que faut-il encore vérifier ?","options":["Uniquement la case cochée.","Son effet observable et les difficultés restantes.","La sympathie du responsable."],"question_type":"qcm_single","is_critical":false},{"question":"Une absence survient sur un poste à risque. Que ne faut-il pas faire ?","options":["Revoir les priorités.","Vérifier les compétences disponibles.","Affecter sans formation une personne pour maintenir le volume."],"question_type":"situation","is_critical":true},{"question":"Le délai d’affichage du planning est-il fixé universellement par ce cours ?","options":["Non ; vérifier les règles et accords applicables avec le relais compétent.","Oui, toujours deux semaines.","Non ; aucune règle ne s’applique."],"question_type":"qcm_single","is_critical":false}],"video":{"title":"Une mission comprise, une amélioration vérifiée","scenes":[{"heading":"Une consigne ne suffit pas","lines":["Résultat attendu","Moyens et limites","Point de suivi"],"narration":"Déléguer, ce n’est pas seulement donner une tâche. Il faut un résultat attendu, des moyens, des limites de décision et un point de suivi. Demandez une reformulation : que faut-il faire, avec quoi et à qui demander de l’aide ? Une tâche nouvelle nécessite une démonstration adaptée."},{"heading":"Cas fictif : les dates dépassées","lines":["Des retraits se répètent","La cause n’est pas établie","Observer avant de juger"],"narration":"Dans ce cas pédagogique fictif, des produits dépassés sont retirés plusieurs fois. Demander seulement d’aller plus vite ne prouve rien sur la cause. Observez le rangement, le contrôle, la commande et le temps disponible. Un manque de moyen ou une consigne imprécise ne se corrige pas avec une injonction générale."},{"heading":"Un brief relié au travail réel","lines":["Priorité et risque","Répartition et moyens","Question et relais possibles"],"narration":"Le brief précise la priorité, le risque important et la répartition. L’équipe doit pouvoir signaler ce qui manque. Sa durée dépend du contexte. Les règles de planning et de repos doivent être vérifiées avec les textes et accords applicables. N’affectez pas une personne non formée à un poste dangereux pour maintenir un volume."},{"heading":"Un signalement n’est pas un conflit banal","lines":["Protéger les personnes","Recueillir les faits discrètement","Solliciter les relais prévus"],"narration":"Un désaccord courant et un signalement de violence ou de harcèlement ne se traitent pas de la même façon. N’imposez pas automatiquement une confrontation commune. Préservez les personnes, recueillez les faits avec discrétion et sollicitez les relais prévus. La méthode ne doit pas ajouter une nouvelle exposition."},{"heading":"Vérifier l’effet de l’action","lines":["Responsable et échéance","Preuve observable","Retour de l’équipe"],"narration":"Une action corrective précise le responsable, les moyens, l’échéance et la preuve d’effet. Une case cochée ou un indicateur en baisse ne suffit pas. Vérifiez sur le terrain et demandez le retour de l’équipe. Moins de retraits ne constitue pas un progrès si les produits ne sont plus contrôlés."},{"heading":"Votre exercice : une action complète","lines":["Décrire les faits","Choisir un changement réalisable","Prévoir sa vérification"],"narration":"Mettez la vidéo en pause. Préparez le brief et la fiche d’action du cas écrit. Faites reformuler par un collègue, puis expliquez comment vous vérifierez le changement. Le quiz final reprend les décisions essentielles ; l’observation d’un brief réel complète l’apprentissage du management de proximité."}]}}$program$::jsonb,$media${"key":"management","version":"2026-11-03","duration_seconds":113.41746,"size_bytes":1426740,"sha256":"8a124951c3ecae2fa3a8d23e9ae687c6fa0793bb9bc596d35c93602141574f05","width":1280,"height":720,"video_codec":"h264","audio_codec":"aac","narration":"synthetic","voice":"fr_FR-siwis-medium","voice_dataset_license":"CC-BY-4.0","voice_model_card":"https://huggingface.co/rhasspy/piper-voices/blob/main/fr/fr_FR/siwis/medium/MODEL_CARD","captions_burned_in":true,"caption_cues":40,"chapters":[{"title":"Une consigne ne suffit pas","seconds":0.0},{"title":"Cas fictif : les dates dépassées","seconds":17.955},{"title":"Un brief relié au travail réel","seconds":37.526},{"title":"Un signalement n’est pas un conflit banal","seconds":58.316},{"title":"Vérifier l’effet de l’action","seconds":77.062},{"title":"Votre exercice : une action complète","seconds":94.822}]}$media$::jsonb,'library/2026-11-03/management/8a124951c3ecae2fa3a8d23e9ae687c6fa0793bb9bc596d35c93602141574f05.mp4') on conflict(program_key,version) do nothing;
insert into opspilot_private.training_programs(program_key,version,payload,media_manifest,object_path) values('manutention','2026-11-03',$program${"key":"manutention","version":"2026-11-03","title":"Manutention : préparer le déplacement avant de porter","category":"Sécurité au travail","summary":"Éviter les ports inutiles, préparer le trajet et demander l’aide adaptée aux charges du poste.","audience":"Équipes manipulant manuellement cartons, bacs, marchandises, équipements ou charges en magasin et en restauration.","prerequisites":"Connaître les aides disponibles et disposer d’un encadrement pour l’entraînement pratique au poste.","requirement":"internal_required","applicability":"Pour les salariés dont l’activité comporte de la manutention manuelle : information sur les risques et formation adaptée, essentiellement pratique. À compléter avec les charges et conditions réelles.","onsite":"Observer un déplacement réel, choisir une aide, préparer le chemin et s’entraîner sous encadrement avec une charge adaptée. Le responsable vérifie l’organisation et les gestes ; aucun seuil universel de poids n’est donné par l’app.","objectives":["Analyser la charge, le trajet et la fréquence avant le déplacement.","Choisir une aide ou une organisation réduisant le port manuel.","Reconnaître une situation nécessitant l’arrêt et un relais."],"positioning":["Identifiez-vous une aide disponible pour les charges de votre poste ?","Savez-vous qui demander quand une charge paraît inadaptée ?","Pouvez-vous repérer un obstacle avant de saisir un colis ?"],"reading_minutes":10,"activity_minutes":12,"sources":[{"label":"Code du travail, R4541-8 : formation adaptée et essentiellement pratique","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000018528891/"}],"chapters":[{"title":"La meilleure charge est parfois celle qu’on ne porte pas","body":"# Analyser la tâche complète\nLa manutention ne se réduit pas au moment où l’on soulève. Elle comprend la prise, le déplacement, la dépose, la répétition et les contraintes de l’environnement. Avant d’agir, regardez la stabilité du colis, sa prise possible, son encombrement, la hauteur de départ et d’arrivée, le trajet et la fréquence. Une charge légère répétée ou éloignée du corps peut aussi poser problème.\n\nCherchez d’abord à éviter ou à réduire le port : livrer plus près de la zone utile, fractionner si le conditionnement le permet, utiliser une aide de manutention ou changer l’organisation. Une aide doit être adaptée à la tâche et utilisée par une personne formée à cet équipement. Un transpalette ou un chariot ne rend pas sûr un trajet encombré.\n\nCas pédagogique fictif : un carton volumineux masque les pieds et doit passer par une porte puis une marche. Le prendre seul « parce qu’il n’est pas très lourd » ignore la visibilité et l’obstacle. Préparez le chemin et demandez une solution adaptée au responsable : aide, autre itinéraire ou organisation différente.\n\nIl n’existe pas ici de poids recommandé valable pour toute personne et toute situation. Les capacités, restrictions connues par les interlocuteurs compétents, prises, distances et répétitions changent l’évaluation. Si une tâche vous paraît inadaptée, signalez-la sans attendre une douleur pour demander une correction."},{"title":"Préparer, déplacer et déposer avec contrôle","body":"# Le geste dépend de la situation réelle\nLa formation pratique doit montrer comment se placer, prendre la charge, se déplacer et la déposer dans le contexte du poste. Préparez une zone de dépose stable et accessible. Évitez les mouvements brusques, les torsions sous charge et les situations où la charge échappe à la prise. Une phrase comme « pliez les genoux » ne suffit pas à rendre toute manutention sûre.\n\nPour un déplacement à plusieurs, convenez de la manœuvre avant de commencer : qui coordonne, quand prendre et déposer, où passer et comment s’arrêter. Porter à deux sans coordination peut créer une chute de charge ou un déséquilibre. Ne placez pas les mains dans une zone de pincement et n’essayez pas de rattraper un colis qui tombe au risque d’être blessé.\n\nSi le trajet est glissant, si la charge bouge ou si la destination n’est pas libre, interrompez l’opération avant de vous retrouver engagé. Signalez le problème. En cas de douleur ou d’incident, cessez la tâche concernée, prévenez le relais prévu et demandez une prise en charge adaptée. Les informations de santé détaillées se traitent avec les interlocuteurs compétents, pas dans une discussion d’équipe ouverte.\n\nLe retour d’expérience sert à modifier le travail : hauteur d’une étagère, conditionnement, fréquence ou disponibilité d’une aide. Une formation efficace ne fait pas porter toute la prévention sur la vigilance du salarié ; elle aide aussi à repérer ce que l’organisation doit corriger."},{"title":"Observer et essayer avec encadrement","body":"# Exercice pratique au poste\nAvec le responsable, choisissez une tâche habituelle et une charge adaptée à l’exercice. Avant toute prise, décrivez le trajet, la dépose, la prise disponible et l’aide envisageable. Produisez une fiche courte : risque observé, solution choisie, personne à prévenir si la situation change.\n\nCas pédagogique fictif : un bac doit être déplacé d’une étagère haute vers un chariot ; son contenu n’est pas stable. La réponse attendue n’est pas de trouver un mouvement héroïque. Il faut revoir la tâche, l’accès, le conditionnement ou l’aide avec le responsable avant de porter. N’utilisez pas une caisse comme marchepied.\n\nCritères observés : analyse avant prise ; trajet et dépose préparés ; aide choisie avec son mode d’emploi ; communication claire ; arrêt si la situation ne permet plus un déplacement maîtrisé. Le responsable fait démontrer, corrige et fait recommencer si nécessaire. L’apprenant explique ensuite pourquoi la solution est adaptée à cette tâche.\n\nPour un débutant, commencez par le repérage sans charge puis une démonstration commentée. Pour approfondir, comparez deux organisations et retenez celle qui réduit la manutention répétée. Le quiz qui suit mesure les choix de prévention ; il ne constitue pas la preuve que l’entraînement pratique a été réalisé ni une aptitude médicale."}],"quiz":[{"question":"Avant de saisir un carton volumineux, que faut-il examiner ?","options":["Le poids seulement.","La charge, la prise, le trajet, la dépose et les aides possibles.","La rapidité des collègues."],"question_type":"qcm_single","is_critical":false},{"question":"Un carton cache vos pieds et le trajet comporte une marche. Quelle décision prendre ?","options":["Avancer sans regarder.","Le porter plus haut devant le visage.","Préparer une solution sûre avec le responsable avant de porter."],"question_type":"situation","is_critical":true},{"question":"Quelle mesure réduit d’abord la manutention ?","options":["Réorganiser la livraison ou utiliser une aide adaptée.","Demander à tout le monde d’aller plus vite.","Imposer le même poids à chacun."],"question_type":"qcm_single","is_critical":false},{"question":"Deux personnes portent une charge. Que faut-il prévoir ?","options":["Que la plus forte décide sans parler.","Une coordination de la prise, du trajet, de l’arrêt et de la dépose.","Aucune préparation."],"question_type":"situation","is_critical":false},{"question":"Une charge se met à tomber. Quelle erreur éviter ?","options":["Prévenir les personnes proches.","Se maintenir hors de la chute.","Tenter de la rattraper en s’exposant à l’écrasement."],"question_type":"critical","is_critical":true},{"question":"Que doit compléter ce parcours ?","options":["Une formation pratique adaptée aux manutentions réelles.","Un seuil de poids identique pour tous.","La signature d’un document sans démonstration."],"question_type":"qcm_single","is_critical":false}],"video":{"title":"Avant de porter, changer la situation","scenes":[{"heading":"Porter n’est pas le point de départ","lines":["Peut-on éviter le port ?","Quelle aide est adaptée ?","Quel trajet est sûr ?"],"narration":"La prévention commence avant de saisir une charge. Peut-on éviter le port, rapprocher la livraison ou utiliser une aide adaptée ? La tâche ne se résume pas au poids. La prise, l’encombrement, la hauteur, le trajet et la répétition changent aussi le risque. Une charge légère répétée mérite également une analyse."},{"heading":"Cas fictif : le carton masque le sol","lines":["La visibilité manque","Une marche coupe le trajet","La destination doit être préparée"],"narration":"Dans ce cas pédagogique fictif, un carton vous cache les pieds. Il faut franchir une porte et une marche. Le porter seul parce qu’il paraît léger n’est pas une réponse suffisante. Préparez la dépose et cherchez avec le responsable une autre organisation, une aide ou un trajet réellement sûr."},{"heading":"L’aide doit être adaptée","lines":["Matériel prévu pour la tâche","Mode d’emploi compris","Cheminement libre"],"narration":"Une aide de manutention réduit certains efforts, mais crée aussi des conditions d’utilisation à respecter. Un chariot n’efface pas un sol glissant ou un passage bloqué. Utilisez seulement le matériel prévu et maîtrisé. Aucun poids universel ne garantit que toute personne peut réaliser toute manutention sans risque."},{"heading":"À plusieurs : se coordonner","lines":["Décider avant la prise","Se donner un signal","Prévoir l’arrêt et la dépose"],"narration":"À plusieurs, convenez du mouvement avant de commencer. Qui coordonne ? Quand prendre et déposer ? Comment s’arrêter si le trajet change ? Une manœuvre sans communication peut déséquilibrer l’équipe. Ne placez pas les mains dans une zone de pincement et ne tentez pas de rattraper une charge qui tombe en vous exposant."},{"heading":"Exercice sur votre tâche","lines":["Observer sans charge","Choisir une solution","Démontrer sous encadrement"],"narration":"Mettez la vidéo en pause. Choisissez une manutention habituelle avec le responsable. Décrivez la charge, le chemin et la dépose, puis choisissez une aide ou une modification de la tâche. La démonstration pratique doit utiliser une situation et une charge adaptées. Le responsable observe, corrige et vérifie la compréhension."},{"heading":"La prévention change le travail","lines":["Réduire les ports inutiles","Interrompre une tâche inadaptée","Faire corriger l’organisation"],"narration":"Retenez trois décisions : réduire les ports inutiles, interrompre une opération devenue inadaptée et faire corriger l’organisation. Une vidéo ou un quiz ne remplace pas la formation essentiellement pratique à vos manutentions. Le cours écrit vous aide à préparer cette mise en pratique et à expliquer les choix retenus."}]}}$program$::jsonb,$media${"key":"manutention","version":"2026-11-03","duration_seconds":121.648435,"size_bytes":1506734,"sha256":"b3607137876437cd86168ed8dd022b20be8da53dd7fac440b964a97b4d0b2895","width":1280,"height":720,"video_codec":"h264","audio_codec":"aac","narration":"synthetic","voice":"fr_FR-siwis-medium","voice_dataset_license":"CC-BY-4.0","voice_model_card":"https://huggingface.co/rhasspy/piper-voices/blob/main/fr/fr_FR/siwis/medium/MODEL_CARD","captions_burned_in":true,"caption_cues":42,"chapters":[{"title":"Porter n’est pas le point de départ","seconds":0.0},{"title":"Cas fictif : le carton masque le sol","seconds":22.321},{"title":"L’aide doit être adaptée","seconds":41.067},{"title":"À plusieurs : se coordonner","seconds":60.453},{"title":"Exercice sur votre tâche","seconds":79.628},{"title":"La prévention change le travail","seconds":102.39}]}$media$::jsonb,'library/2026-11-03/manutention/b3607137876437cd86168ed8dd022b20be8da53dd7fac440b964a97b4d0b2895.mp4') on conflict(program_key,version) do nothing;
insert into opspilot_private.training_programs(program_key,version,payload,media_manifest,object_path) values('materiels-produits','2026-11-03',$program${"key":"materiels-produits","version":"2026-11-03","title":"Matériels, produits et protections : utiliser sans improviser","category":"Sécurité au travail","summary":"Vérifier avant usage, suivre les consignes et arrêter une utilisation anormale sans intervention improvisée.","audience":"Personnel utilisant outils, équipements de travail, produits de nettoyage ou équipements de protection au magasin et au restaurant.","prerequisites":"Notices, étiquettes, fiches de données de sécurité et consignes du poste accessibles ; démonstration par une personne compétente.","requirement":"internal_required","applicability":"Selon les équipements, les produits dangereux et les protections réellement utilisés : information et formation adaptées, renouvelées lorsque nécessaire. Les autorisations spécifiques restent hors du périmètre de ce module interne.","onsite":"Démonstration sur chaque équipement concerné, lecture d’une étiquette et d’une fiche de données de sécurité, choix et entraînement aux protections prévues. Vérifier l’arrêt normal et le relais en cas de défaut sans créer une situation dangereuse.","objectives":["Vérifier l’état et les conditions d’emploi avant l’utilisation.","Retrouver une précaution dans la notice, l’étiquette ou la fiche de données de sécurité.","Arrêter l’usage et solliciter le relais adapté en cas de défaut."],"positioning":["Savez-vous quel matériel vous êtes formé à utiliser ?","Savez-vous retrouver la fiche du produit de nettoyage de votre poste ?","Pouvez-vous expliquer le choix et les limites des protections prévues ?"],"reading_minutes":11,"activity_minutes":12,"sources":[{"label":"Code du travail, R4323-1 à R4323-5 : équipements de travail","url":"https://www.legifrance.gouv.fr/codes/section_lc/LEGITEXT000006072050/LEGISCTA000018489707/"},{"label":"Code du travail, R4323-106 : entraînement aux protections individuelles","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000018531280/"},{"label":"Code du travail, R4412-38 : information et formation au risque chimique","url":"https://www.legifrance.gouv.fr/codes/article_lc/LEGIARTI000036483735/"}],"chapters":[{"title":"Un équipement connu et vérifié","body":"# L’habitude ne remplace pas la consigne\nAvant d’utiliser un équipement, identifiez la tâche autorisée, les protections, les limites d’emploi et la conduite à tenir en situation anormale. La notice et la consigne du poste donnent les repères ; une démonstration permet de les relier au matériel réel. Ne supposez pas que deux modèles proches se commandent de la même manière.\n\nContrôlez ce qui est prévu avant usage : état apparent, stabilité, accessoires, protecteurs et zone de travail. Un bruit inhabituel, une pièce abîmée ou un protecteur manquant impose d’arrêter l’utilisation concernée et de prévenir le relais compétent. N’effectuez pas de réparation improvisée et ne neutralisez pas un dispositif de sécurité.\n\nCas pédagogique fictif : un produit est coincé dans une machine et un collègue propose de pousser la main derrière le protecteur. Refusez cette manœuvre et appliquez l’arrêt et le relais prévus. Un simple bouton arrêté ne garantit pas que toutes les énergies sont maîtrisées. Le déblocage, le nettoyage exposant à un mécanisme ou une maintenance relèvent de procédures et de personnes compétentes.\n\nPour les outils manuels, adaptez aussi la méthode : outil en bon état, support stable, direction de coupe maîtrisée, mains et collègues hors de la trajectoire. N’utilisez pas un outil pour une fonction non prévue. Le responsable observe l’essai et complète la formation lorsque le matériel ou les conditions d’emploi changent."},{"title":"Produit identifié, protection adaptée","body":"# Lire avant de doser ou de transvaser\nUn produit de nettoyage se choisit pour un usage défini. L’étiquette précise les dangers et les précautions ; la fiche de données de sécurité apporte notamment les informations de protection, de stockage et de conduite en cas d’exposition. Demandez où se trouvent ces fiches et comment appliquer les consignes du site.\n\nNe mélangez pas des produits pour renforcer leur efficacité et ne transvasez jamais dans un emballage alimentaire. Utilisez le contenant et l’identification prévus. Respectez la dilution, la ventilation, le temps de contact et le rinçage lorsqu’ils sont prescrits. Ne modifiez pas ces paramètres en vous fondant sur l’odeur ou l’apparence.\n\nLes protections individuelles dépendent du produit et de la tâche. Des gants quelconques ne protègent pas de tout ; un gant détérioré ou inadapté peut être inefficace. Le responsable doit expliquer le choix, la mise en place, le retrait, l’entretien et les limites de la protection, avec entraînement si nécessaire. Les protections ne remplacent pas les mesures collectives prévues.\n\nEn cas de projection, fuite ou malaise, arrêtez la tâche, évitez d’exposer d’autres personnes et appliquez immédiatement les consignes d’urgence et les instructions des secours. Rendez disponible l’identification du produit aux personnes qui interviennent. Ne tentez pas une neutralisation chimique improvisée. L’exercice de ce cours ne prévoit aucun mélange ni exposition réelle."},{"title":"Décrire puis démontrer la bonne utilisation","body":"# Atelier encadré sans mise en danger\nChoisissez avec le responsable un équipement du poste et un produit réellement utilisé. Montrez la consigne et la fiche associée. Avant toute manipulation, expliquez l’usage prévu, une situation anormale et le relais à prévenir. Décrivez les contrôles à faire puis réalisez un essai selon la procédure, sous encadrement.\n\nCas pédagogique fictif : un flacon sans étiquette est posé à côté d’un produit connu. Le collègue affirme que c’est le même. La réponse attendue est de ne pas l’utiliser, d’éviter qu’il soit pris par erreur et de demander son identification et son traitement selon la procédure. Deviner le contenu en le sentant ou en le mélangeant constitue une exposition inutile.\n\nLivrable : une fiche pratique comportant tâche, matériel ou produit, consigne accessible, protection prévue, défaut entraînant l’arrêt et fonction du relais. Aucun mot de passe, donnée de santé ou identité de client n’y est nécessaire.\n\nCritères observés : document pertinent retrouvé ; conditions d’emploi expliquées ; protection adaptée démontrée ; arrêt et signalement corrects face à un défaut fictif. Pour un débutant, le responsable réalise d’abord une démonstration commentée. Pour approfondir, l’apprenant explique ce qui change lorsque le modèle ou le produit est remplacé. Le quiz final vérifie les décisions ; il n’attribue aucune autorisation de conduite, habilitation électrique ou certification technique."}],"quiz":[{"question":"Une machine est bloquée. Peut-on passer la main derrière un protecteur ?","options":["Oui, si l’on va vite.","Non ; appliquer l’arrêt et le relais compétent prévus.","Oui, si un collègue surveille."],"question_type":"situation","is_critical":true},{"question":"Un flacon n’a plus d’étiquette. Quelle décision prendre ?","options":["Le sentir pour l’identifier.","Le mélanger au produit habituel.","Ne pas l’utiliser et demander son traitement selon la procédure."],"question_type":"situation","is_critical":true},{"question":"Où vérifier les précautions d’un produit dangereux ?","options":["Dans l’étiquette, la fiche de données de sécurité et les consignes du site.","Uniquement dans les habitudes d’un collègue.","Dans une publicité générale."],"question_type":"qcm_single","is_critical":false},{"question":"Que faire lorsqu’un produit ou un équipement change ?","options":["Conserver automatiquement l’ancienne méthode.","Revoir les instructions et compléter la formation adaptée.","Essayer d’abord sans protection."],"question_type":"qcm_single","is_critical":false},{"question":"Quels gants choisir ?","options":["N’importe quels gants propres.","Les plus épais sans autre vérification.","Ceux prévus pour le produit et la tâche, en bon état et correctement utilisés."],"question_type":"qcm_single","is_critical":false},{"question":"Peut-on améliorer un produit en le mélangeant à un autre ?","options":["Non ; respecter les usages et ne pas improviser de mélange.","Oui, si les odeurs sont proches.","Oui, avec un récipient alimentaire."],"question_type":"critical","is_critical":true}],"video":{"title":"Utiliser sans improviser","scenes":[{"heading":"Connaître avant d’utiliser","lines":["La tâche autorisée","La consigne du modèle","Le relais en cas de défaut"],"narration":"Un équipement familier n’est pas automatiquement maîtrisé. Avant de l’utiliser, connaissez la tâche autorisée, les protections et la conduite à tenir si quelque chose est anormal. Deux modèles proches peuvent fonctionner différemment. Une démonstration sur le matériel réel relie la notice à votre travail."},{"heading":"Cas fictif : la machine bloque","lines":["Ne pas contourner le protecteur","Arrêter selon la procédure","Prévenir la personne compétente"],"narration":"Dans ce cas pédagogique fictif, un produit se coince dans une machine. Un collègue propose de passer la main derrière le protecteur. Ne le faites pas. Appliquez l’arrêt et le relais prévus. Un bouton arrêté ne garantit pas que toutes les énergies sont maîtrisées. Le déblocage et la maintenance ne s’improvisent pas."},{"heading":"Le produit doit être identifié","lines":["Étiquette lisible","Fiche de sécurité accessible","Usage et dilution respectés"],"narration":"Pour un produit de nettoyage, l’étiquette et la fiche de données de sécurité donnent les précautions à appliquer. Ne devinez pas le contenu d’un flacon sans étiquette. Ne mélangez pas les produits pour renforcer leur effet et ne les transvasez pas dans un emballage alimentaire. Respectez l’usage et la dilution prévus."},{"heading":"Une protection adaptée à la tâche","lines":["Choisir le bon équipement","Vérifier son état","S’entraîner à le porter"],"narration":"Une protection individuelle doit être adaptée au risque. Des gants quelconques ne protègent pas de tout. Vérifiez leur état et apprenez la mise en place, le retrait et l’entretien prévus. La protection ne remplace pas les mesures collectives. Si le produit ou le matériel change, faites revoir les consignes et la formation nécessaire."},{"heading":"Votre atelier encadré","lines":["Retrouver une consigne","Montrer les vérifications","Expliquer l’arrêt et le relais"],"narration":"Mettez la vidéo en pause. Avec le responsable, choisissez un matériel et un produit du poste. Retrouvez leurs consignes. Expliquez une anomalie qui impose l’arrêt, puis démontrez les contrôles et les protections sans créer de danger. L’exercice ne comporte aucun mélange de produit ni essai dangereux."},{"heading":"Trois décisions à retenir","lines":["Vérifier avant usage","Respecter les limites","Alerter sans réparer au hasard"],"narration":"Retenez ces trois décisions : vérifier avant usage, respecter les limites et alerter sans réparation improvisée. Le texte et le quiz reprennent ces choix. La démonstration pratique reste à organiser sur chaque matériel concerné ; cette capsule ne délivre aucune habilitation ou autorisation technique."}]}}$program$::jsonb,$media${"key":"materiels-produits","version":"2026-11-03","duration_seconds":115.588481,"size_bytes":1407454,"sha256":"365f8f07fd72c50cc98748de421dc97515dd869ba83bc5ef28a5255e439848ec","width":1280,"height":720,"video_codec":"h264","audio_codec":"aac","narration":"synthetic","voice":"fr_FR-siwis-medium","voice_dataset_license":"CC-BY-4.0","voice_model_card":"https://huggingface.co/rhasspy/piper-voices/blob/main/fr/fr_FR/siwis/medium/MODEL_CARD","captions_burned_in":true,"caption_cues":39,"chapters":[{"title":"Connaître avant d’utiliser","seconds":0.0},{"title":"Cas fictif : la machine bloque","seconds":18.421},{"title":"Le produit doit être identifié","seconds":37.121},{"title":"Une protection adaptée à la tâche","seconds":55.635},{"title":"Votre atelier encadré","seconds":76.529},{"title":"Trois décisions à retenir","seconds":96.413}]}$media$::jsonb,'library/2026-11-03/materiels-produits/365f8f07fd72c50cc98748de421dc97515dd869ba83bc5ef28a5255e439848ec.mp4') on conflict(program_key,version) do nothing;
